@value unit: var(--ring-unit);

.noResults {
  padding: unit calc(unit * 1.5) calc(unit) calc(unit * 2);
}

.noResultsMessage {
  word-break: break-word;

  color: var(--ring-secondary-color);

  line-height: var(--ring-line-height);
}

.placeholder {
  display: flex;
  align-items: center;
  flex-direction: column;

  flex-grow: 1;

  color: var(--ring-secondary-color);
}

.nothingFoundBox {
  display: flex;
  align-items: center;
  flex-direction: column;

  width: 100%;
  padding: calc(unit * 10) 0;
}

.nothingFoundBox .message {
  margin: unit calc(unit * 2) calc(unit * 3);

  font-size: var(--ring-font-size);
}
