@value unit: var(--ring-unit);

.wrapper {
  font-size: var(--ring-font-size-smaller);
}

.title {
  font-size: inherit;
}

.inlineTitle {
  font-weight: var(--ring-font-weight-bold);
}

.reasonDuration {
  font-weight: var(--ring-font-weight-bold);
}

.popup {
  max-width: calc(unit * 53);

  padding: calc(unit * 1.5);
}

.reason {
  display: grid;
  grid-template-columns: max-content auto;

  row-gap: calc(unit / 2);
  column-gap: unit;

  & .reasonTime {
    padding: 0 unit 0 0;

    text-align: left;

    font-weight: var(--ring-font-weight-bold);
  }
}

.popup .reason {
  grid-template-columns: auto max-content;

  font-size: var(--ring-font-size-smaller);

  & .reasonTime {
    padding: 0 0 0 unit;

    text-align: right;

    font-weight: normal;
  }
}

.popup .lessThanOneSecond {
  color: var(--ring-secondary-color);
}

.inlineReasons {
  margin-bottom: calc(unit / 2);

  font-size: inherit;
}

.dropdown {
  margin-bottom: -1px;
}

.anchor {
  height: auto;

  color: inherit;
}

.iconsOffset {
  display: inline-block;

  width: calc(unit * 2);
}

.queuedIcon {
  margin-left: -1px;

  color: var(--ring-icon-color);
}

.ownQueueTimeIcon {
  composes: queue from '../../pages/BuildPage/DependenciesTab/DependenciesTimeline/Legend/Legend.module.css';
}
