@value unit: var(--ring-unit);
@value heightHeader: calc(unit * 6);

.actionButton {
  padding: calc(unit * 1.5) 0 0 calc(unit / 2);

  opacity: 0;
}

.controls {
  display: grid;

  align-content: space-between;

  width: calc(unit * 9);

  text-align: right;

  & .actionButton {
    transition: opacity var(--ring-ease);
  }
}

.container {
  display: flex;
  flex-direction: column;

  box-sizing: border-box;

  width: 100%;
  margin-bottom: calc(unit);
  padding: calc(unit);

  border-radius: calc(unit * 1.5);
  background-color: var(--ring-secondary-background-color);

  &:hover .actionButton {
    opacity: 1;
  }
}

.header {
  display: flex;
  align-items: start;

  margin-bottom: calc(unit * 1);
}

.buttonsWrapper {
  display: flex;
  align-items: end;
  flex-direction: column;
}

.emailIcon {
  display: flex;
  align-items: center;
  justify-content: center;

  width: calc(unit * 6);
  height: calc(unit * 6);

  margin-right: calc(unit * 1);

  border-radius: calc(unit);
  background-color: var(--ring-tag-background-color);
}

.emailIconImage {
  color: var(--ring-icon-color);

  font-size: calc(unit * 2);
}

.title {
  flex-grow: 1;
}

.notificationText {
  margin: 0;

  padding-bottom: calc(unit * 0.5);

  color: var(--ring-secondary-color);

  font-size: var(--ring-font-size-smaller);
}

.emailNotifierText {
  margin: 0;

  font-size: var(--ring-font-size);
}

.toggleWrapper {
  display: flex;
  align-items: center;
  justify-content: end;
}

.details {
  color: var(--ring-secondary-color);

  font-size: var(--ring-font-size-smaller);
}

.detailText {
  margin: 0;
}

.controlButtons {
  gap: calc(unit / 2);
}

.deleted {
  .emailIcon {
    background-color: var(--ring-content-background-color);
  }

  .emailIconImage {
    color: var(--ring-icon-disabled-color);
    background-color: var(--ring-content-background-color);
  }

  .detailText {
    text-decoration: line-through;

    color: var(--ring-disabled-color);
  }

  .emailNotifierText {
    text-decoration: line-through;

    color: var(--ring-disabled-color);
  }
}
