@value unit: var(--ring-unit);

.heading.heading {
  margin: 0;

  margin-bottom: unit;
  padding: 0;

  font: inherit;
  font-weight: var(--ring-font-weight-bold);
}

.filter {
  display: flex;

  align-items: start;
  flex-direction: column;

  margin-bottom: calc(unit * 2);
}

.changesTypeFilter {
  margin-bottom: calc(unit * 2);
}

.changesTypeFilter,
.changesFilter {
  margin-right: calc(unit * 2);

  &:last-child {
    margin-right: 0;
  }
}

.showAllButton {
  margin-top: unit;
}

.emptyList {
  color: var(--ring-secondary-color);

  font-size: var(--ring-font-size-smaller);
}

.count {
  margin-left: unit;

  color: var(--ring-secondary-color);
}
