@value unit: var(--ring-unit);

:root {
  --tc-message-background-color: rgba(17, 19, 20, 0.9);
  --tc-error-background-color: var(--ring-removed-subtle-background-color);
  --tc-error-hover-color: var(--ring-error-color);
  --tc-success-background-color: #e6f2e9;
  --tc-success-hover-background-color: #bcdcc2;
  --tc-success-progress-color: var(--ring-main-success-color);
  --tc-classic-highlight-color: #ffc;
  --tc-changes-graph-background-color: #333;
  --tc-changes-graph-color: #bbb;
  --tc-classic-disabled-input-color: var(--ring-disabled-color);
  --tc-highlight-color: #ff008c;
  --tc-page-padding-inline: calc(unit * 3);
}

:global(.ring-ui-theme-dark),
:global(.ring-variables_dark-dark) {
  --tc-error-hover-color: #f8b4b8;
  --tc-success-background-color: #1f4d28;
  --tc-success-hover-background-color: #317c40;
  --tc-classic-highlight-color: #593d01;
  --tc-classic-disabled-input-color: rgba(var(--ring-text-components), 0.5);
  --tc-highlight-color: #e56ab6;
}

/* stylelint-disable selector-class-pattern */
:global(.settings-mode.ring-variables-light),
:global(.settings-mode .ring-variables-light) {
  --ring-link-components: 85, 69, 197; /* #5545c5 */
  --ring-link-hover-components: 62, 51, 140; /* #3e338c */
  --ring-action-link-components: 85, 69, 197; /* #5545c5 */
  --ring-main-components: 111, 92, 255; /* #6f5cff */
  --ring-button-primary-background-components: 111, 92, 255; /* #6f5cff */
  --ring-button-primary-border-components: 85, 69, 197; /* #5545c5 */
  --ring-main-hover-components: 105, 85, 247; /* #6955f7 */
  --ring-border-hover-components: 165, 153, 255; /* #a599ff */
  --ring-border-disabled-active-components: 214, 209, 255; /* #d6d1ff */
  --ring-sidebar-background-components: 247, 246, 255; /* #f7f6ff */
  --ring-hover-background-components: 243, 243, 255; /* #f3f3ff */
  --ring-selected-background-components: 214, 209, 255; /* #d6d1ff */
}

:global(.settings-mode.ring-variables_dark-dark.ring-variables_dark-dark),
:global(.settings-mode .ring-variables_dark-dark.ring-variables_dark-dark),
:global(.settings-mode.ring-ui-theme-dark.ring-ui-theme-dark),
:global(.settings-mode .ring-ui-theme-dark.ring-ui-theme-dark) {
  --ring-link-components: 196, 189, 255; /* #c4bdff */
  --ring-link-hover-components: 165, 153, 255; /* #a599ff */
  --ring-action-link-components: 196, 189, 255; /* #c4bdff */
  --ring-main-components: 111, 92, 255; /* #6f5cff */
  --ring-button-primary-background-components: 111, 92, 255; /* #6f5cff */
  --ring-button-primary-border-components: 196, 189, 255; /* #c4bdff */
  --ring-main-hover-components: 85, 69, 197; /* #5545c5 */
  --ring-border-hover-components: 85, 69, 197; /* #5545c5 */
  --ring-border-disabled-active-components: 42, 36, 91; /* #2a245b */
  --ring-sidebar-background-components: 43, 43, 48; /* #2b2b30 */
  --ring-hover-background-components: 26, 23, 53; /* #1a1735 */
  --ring-selected-background-components: 62, 51, 140; /* #3e338c */
}
/* stylelint-enable */

/* Metrics */
.font {
  composes: ring-global-font from global;
}

/* stylelint-disable selector-class-pattern */
.font-lower {
  composes: ring-global-font from global;
  composes: ring-global-font-lower from global;
}

.font-smaller {
  composes: ring-global-font from global;
  composes: ring-global-font-lower from global;
  composes: ring-global-font-smaller from global;
}

.font-smaller-lower {
  composes: ring-global-font from global;
  composes: ring-global-font-smaller from global;
  composes: ring-global-font-smaller-lower from global;
}

.font-larger {
  composes: ring-global-font from global;
  composes: ring-global-font-larger-lower from global;
  composes: ring-global-font-larger from global;
}
/* stylelint-enable */

.ellipsis {
  composes: ring-global-ellipsis from global;
}

.resetButton {
  composes: ring-global-resetButton from global;
}

/* Media breakpoints (minimal values) */
@value breakpoint-middle: 960px;
@value breakpoint-large: 1200px;

/* Media queries */
@value large-screen-media: (min-width: breakpoint-large);

/* https://a11yproject.com/posts/how-to-hide-content/ */

/* stylelint-disable-next-line selector-max-specificity */
.visuallyHidden,
.visuallyHiddenContainer:not(:hover, :global(.focusVisible), :active) .visuallyHiddenChild {
  position: absolute;

  overflow: hidden;
  clip: rect(1px, 1px, 1px, 1px);

  width: 1px;
  height: 1px;

  white-space: nowrap; /* added line */
}

.lineClamp {
  position: relative;

  overflow: hidden;
  overflow-wrap: break-word;
}

.lineClampHasOverflow::after {
  position: absolute;
  right: 0;
  bottom: 0;
  left: 0;

  padding-top: 1px;

  content: '\2060';

  background-image: linear-gradient(to right, rgba(255, 255, 255, 0), rgba(255, 255, 255, 1));
}

@supports (-webkit-line-clamp: 2) {
  .lineClamp {
    display: -webkit-box;

    -webkit-box-orient: vertical;

    text-overflow: ellipsis;
  }

  .lineClampHasOverflow::after {
    display: none;
  }
}

/* stylelint-disable selector-class-pattern */
:global {
  .tc-icon_space,
  .tc-icon_space_disabled {
    background-image: url('../logos/space.svg');
    background-position: 50% 55%;
    background-size: 130% 130%;
  }

  .tc-icon_space_disabled {
    filter: grayscale(1) contrast(0.1) brightness(1.84);
  }

  .ring-ui-theme-dark .tc-icon_space_disabled {
    filter: brightness(0.7) grayscale(1);
  }

  .loginIcon_github,
  .loginIcon_github-enterprise,
  .loginIcon_gitlab,
  .loginIcon_gitlab-enterprise,
  .loginIcon_bitbucket,
  .loginIcon_azure,
  .loginIcon_space,
  .loginIcon_google {
    display: inline-block;

    width: 50px;
    height: 50px;
    margin: 10px 10px 0;

    transition: 0.2s;

    background-repeat: no-repeat;
    background-position: center;
  }

  .loginIcon_github {
    background-image: url('../logos/github.svg');
    background-size: 90%;
  }

  .loginIcon_github-enterprise {
    background-image: url('../logos/github-enterprise.svg');
    background-size: 90%;
  }

  .loginIcon_gitlab {
    background-image: url('../logos/gitlab.svg');
    background-size: 100%;
  }

  .loginIcon_gitlab-enterprise {
    background-image: url('../logos/gitlab.svg');
    background-size: 100%;
  }

  .loginIcon_bitbucket {
    background-image: url('../logos/bitbucket.svg');
    background-size: 130%;
  }

  .loginIcon_azure {
    background-image: url('../logos/azure-devops.svg');
    background-size: 80%;
  }

  .loginIcon_space {
    background-image: url('../logos/space.svg');
    background-size: 100%;
  }

  .loginIcon_google {
    background-image: url('../logos/google.svg');
    background-size: 100%;
  }

  .loginIcon_github:hover,
  .loginIcon_github-enterprise:hover,
  .loginIcon_gitlab:hover,
  .loginIcon_gitlab-enterprise:hover,
  .loginIcon_bitbucket:hover,
  .loginIcon_azure:hover,
  .loginIcon_space:hover,
  .loginIcon_google:hover {
    width: 60px;
    height: 60px;
    margin-top: 0;
    margin-right: 5px;
    margin-left: 5px;
  }
}
/* stylelint-enable */
