@value unit: var(--ring-unit);

.table {
  display: grid;
  grid-template-columns: 1fr auto;

  align-items: stretch;

  & .tableHeader {
    color: var(--ring-secondary-color);

    font-size: var(--ring-font-size-smaller);
  }

  & .tableTh {
    padding-bottom: unit;

    border-bottom: 1px solid var(--ring-line-color);
  }

  & .tableTd {
    padding-top: unit;
    padding-bottom: unit;

    border-bottom: 1px solid var(--ring-line-color);
  }

  & .tableKeyName {
    display: flex;
    gap: var(--ring-unit);

    & svg {
      flex-shrink: 0;

      width: 12px;
      height: 12px;

      margin-top: calc(unit / 2);
    }
  }
}

.actionButtons {
  display: flex;

  justify-content: end;

  gap: unit;
}
