@value unit: var(--ring-unit);

.actions {
  display: inline-flex;
  align-items: baseline;

  & > :not(:last-child) {
    margin-right: calc(unit * 1.5);
  }
}

.secondary {
  padding: 0;
}

.close {
  height: auto;
  margin-left: unit;

  line-height: inherit;
}

.popupMenu {
  z-index: var(--ring-alert-z-index);
}
