@value unit: var(--ring-unit);

.container {
  padding: calc(unit * 1.8) 0 0 calc(unit * 2.2);
}

.button {
  display: block;
  overflow: hidden;

  width: 100%;

  height: auto;
  padding-right: 0;
  padding-left: 0;

  text-align: left;

  white-space: nowrap;
  text-overflow: ellipsis;

  color: var(--ring-text-color);

  font-size: var(--ring-font-size);
  font-weight: var(--ring-font-weight-bold);
}

.button:hover {
  color: var(--ring-link-hover-color);
}

.chevron.chevron {
  color: var(--ring-icon-secondary-color);
}

.border {
  padding-bottom: calc(unit * 1.5);

  border-bottom: calc(unit / 2) solid var(--ring-secondary-background-color);
}

.subTitle {
  padding-top: calc(unit / 4);
  padding-right: unit;
  padding-left: calc(unit * 2.5);

  color: var(--ring-secondary-color);

  font-size: var(--ring-font-size-smaller);
  line-height: var(--ring-line-height-lowest);
}
