@value unit: var(--ring-unit);

.inactiveKeys {
  display: flex;
  flex-direction: column;
  row-gap: calc(unit * 1.5);
}

.heading.heading {
  margin: 0;

  font-size: 16px;
  font-weight: var(--ring-font-weight-bold);
}

.toggle {
  padding-right: 0;
  padding-left: 0;

  color: inherit;

  font-size: inherit;
  font-weight: inherit;
  line-height: inherit;
}

.checkbox {
  left: 4px;
}

.licenseKeysTable {
  composes: licenseKeysTable from '../ActiveLegacyLicenses/ActiveLegacyLicenses.module.css';

  width: 100%;

  & td:first-child,
  & th:first-child {
    white-space: normal;
  }

  & td:last-child,
  & th:last-child {
    width: 0%;
  }
}

/* .readOnly td:first-child, */
.readOnly td:last-child,
/*.readOnly th:first-child,*/
.readOnly th:last-child {
  width: auto;
}

.warn {
  color: var(--ring-error-color);
}
