@value unit: var(--ring-unit);

.item {
  padding-left: 0;

  border-radius: calc(unit / 2);

  line-height: 24px;
}

.itemWrapper {
  background-color: var(--ring-sidebar-background-color);
}

.item,
.itemWrapper,
.hoverableLink {
  flex-grow: 1;

  outline: none;
}

.hoveredItem,
.hoverableItem:hover {
  background-color: var(--ring-tag-background-color);
}

.item.activeItem,
.item.highlightedItem {
  background-color: var(--ring-selected-background-color);
}

.hoverableLink:hover {
  text-decoration-line: none;

  color: var(--ring-text-color);
}

.counter {
  margin: 0 8px;
}

.itemWrapper:focus-visible,
.item:focus-visible,
.focusedItem {
  box-sizing: border-box;

  border-radius: calc(unit / 2);
  box-shadow: inset 0 0 0 2px var(--ring-border-hover-color);
}

.itemWrapper:focus,
.item:focus,
.focusedItem {
  outline: none;
}

@value unit: unit;

.icon {
  margin: 0 6px 0 0;
}

.overview {
  display: flex;
  align-items: center;
}

.selectHoverFocus {
  box-sizing: border-box;
  width: calc(100% - unit * 3) !important;
  margin: 0 calc(unit * 1.5) !important;

  border-radius: calc(unit / 2);
}

.selectHoverFocus:focus-within {
  border-radius: calc(var(--ring-unit) / 2);
  outline: none;
  box-shadow: inset 0 0 0 2px var(--ring-border-hover-color);
}

.selectHoverFocus:focus {
  outline: none;
}

.title {
  display: flex;

  padding: 0 calc(unit * 1.5) calc(unit - 2px) calc(unit * 2);

  letter-spacing: 1px;

  font-size: var(--ring-font-size-smaller);
  font-weight: var(--ring-font-weight-bold);
  line-height: var(--ring-line-height-lower);
}

.popup {
  display: flex;
  align-items: center;

  height: 24px;
}
