@value unit: var(--ring-unit);

.sidebar {
  z-index: var(--ring-alert-z-index);

  width: 100%;
  height: 100%;
  min-height: 100%;

  background-color: var(--ring-content-background-color);
}

.content {
  min-height: calc(100% - calc(unit * 8));

  & .textInfo {
    padding: calc(unit * 1.5) 0 0 calc(unit * 2);
  }
}

.label {
  display: block;

  margin-bottom: calc(unit / 4);

  color: var(--ring-secondary-color);

  font-size: var(--ring-font-size-smaller);
}

.disabledIcon {
  opacity: 0.5;
}

.usedVcsRootAlert {
  margin-bottom: unit;
}

.repositoryBlock {
  display: flex;
  flex-direction: column;
  row-gap: unit;
}

.controls {
  display: flex;
  flex-direction: column;
  gap: unit;
}

.loginAlertContent {
  display: flex;

  column-gap: unit;
}

.loginLink {
  margin-left: auto;

  text-wrap: nowrap;
}

.form {
  display: flex;
  flex-direction: column;

  margin-top: calc(unit * 1.5);

  row-gap: calc(unit * 1.5);
}

.branchSpecPolicy {
  padding-left: 1px;
}
