@value unit: var(--ring-unit);

.row {
  display: contents;

  &::before {
    position: absolute;

    z-index: 1;
    top: var(--absolute-child-top);
    right: 0;
    bottom: 0;
    left: 0;

    content: '';
    pointer-events: none;

    border-bottom: 1px solid var(--ring-line-color);

    grid-column: start / end;
    grid-row: var(--row) / span 1;
  }
}

.expanded {
  &::before {
    position: absolute;

    z-index: 1;
    top: var(--absolute-child-top);
    right: calc(var(--tc-page-padding-inline) * -1);
    bottom: 0;
    left: calc(var(--tc-page-padding-inline) * -1);

    content: '';
    pointer-events: none;

    box-shadow:
      0 0 0 1px var(--ring-line-color),
      0 2px 8px var(--ring-popup-shadow-color);

    grid-column: start / end;
    grid-row: var(--row) / span 2;
  }
}

.details {
  display: contents;
}

.button {
  &::before {
    position: absolute;
    top: 0;
    right: calc(var(--tc-page-padding-inline) * -1);
    bottom: 0;
    left: calc(var(--tc-page-padding-inline) * -1);

    content: '';
  }

  grid-column: start / end;
  grid-row: var(--row) / span 1;
}

.button:focus {
  outline: none;
}

.expanded .button {
  &::before {
    border-bottom: 1px solid var(--ring-line-color);
    background-color: var(--ring-hover-background-color);
    box-shadow: inset 2px 0 var(--ring-main-color);
  }
}

.details:hover .button,
.details .button:focus {
  /* stylelint-disable-next-line selector-max-specificity */
  &::before {
    background-color: var(--ring-hover-background-color);
  }
}

.detailsWrapper {
  grid-column: start / end;
}

.arrow {
  position: absolute;

  grid-column: -1;
  grid-row: var(--row) / span 1;

  top: calc(var(--absolute-child-top) + 8px);
  right: calc(unit * -4 + 10px);
  left: auto;

  padding: 0;

  transition: opacity ease;

  pointer-events: none;

  opacity: 0;
  color: var(--ring-icon-secondary-color);

  line-height: normal;
}

.expanded .arrow {
  opacity: 1;
}

.details:hover .arrow,
.button:focus ~ .arrow {
  transition: none;

  opacity: 1;
}

.button:active ~ .arrow {
  transition: none;

  opacity: 1;
  color: var(--ring-main-color);
}
