@value unit: var(--ring-unit);

.container {
  display: flex;
  flex-direction: column;

  height: 100%;
}

.header {
  padding: calc(unit * 2) calc(unit * 2) 14px;

  font-size: 20px;
}

.header :global(.ring-island-title) {
  float: none;
}

.content {
  padding: 0 calc(unit * 2);
}

.releaseHeader {
  display: flex;
  align-items: center;

  min-height: 42px;
  padding-right: unit;
  gap: calc(unit * 1.5);
}

.gift :global(.ring-avatar-avatarInfo) {
  color: var(--ring-link-color);
  background-color: var(--ring-hover-background-color);
}

.releaseIcon.releaseIcon svg {
  vertical-align: -5px;
}

.releaseSubtitle {
  color: var(--ring-secondary-color);
}

.releaseTitle.releaseTitle {
  margin-top: 0;
}

.feedback {
  margin-left: auto;
}

.timeline {
  position: relative;

  padding-top: calc(unit * 2);

  padding-left: calc(unit * 5.5);
}

.timeline::before {
  position: absolute;
  top: -1px;
  bottom: -1px;
  left: 15px;

  width: 2px;

  content: '';

  background-color: var(--ring-line-color);
}

.event {
  padding-bottom: calc(unit * 3);
}

.eventTitle.eventTitle {
  margin: 0 0 calc(unit / 2);

  font-size: var(--ring-font-size);
  line-height: var(--ring-line-height);
}

.tag {
  margin-right: calc(unit / 2);

  pointer-events: none;

  font-weight: normal;
}

.security {
  padding-left: calc(unit / 2);

  color: var(--ring-warning-color);
  background-color: var(--ring-warning-background-color);
}

.securityIcon {
  margin-right: calc(unit / 2);

  color: var(--ring-icon-warning-color);
}

.description img {
  display: block;

  max-width: 100%;
  margin-top: unit;

  border-radius: var(--ring-border-radius-large);
  box-shadow: 0 0 0 1px var(--ring-line-color);
}

.description ul {
  list-style-type: disc;
}

.callToAction {
  display: flex;

  margin-top: unit;
  gap: calc(unit / 2);
}

.oldest {
  margin-bottom: calc(unit * 3);
}

.oldest::before {
  bottom: 10px;
}

.oldest::after {
  position: absolute;
  bottom: 6px;
  left: calc(unit * 1.5);

  width: unit;
  height: unit;

  content: '';

  border-radius: 50%;
  background-color: var(--ring-line-color);
}

.newWindowIcon {
  margin-left: calc(unit / 2);
}
