.item {
  display: flex;

  overflow: hidden;

  white-space: nowrap;
}

.contentWrapper {
  overflow: hidden;
  flex: 1 1 auto;
}

.expandHandle {
  flex: 0 0 auto;
}

.popup {
  padding-left: var(--ring-unit);
}

.tooltip {
  composes: ring-tooltip-tooltip from global;
  composes: ring-tooltip-long from global;

  z-index: var(--ring-alert-z-index);

  align-items: center;

  height: 28px;

  &.inPopup {
    z-index: 1000;
  }
}

.nonInteractivePopup {
  z-index: var(--ring-fixed-z-index);

  overflow: hidden;

  pointer-events: none;
}

.interactivePopup {
  z-index: 0;

  overflow: hidden;
}
