@value unit: var(--ring-unit);

.popup {
  width: calc(unit * 63);
  height: 70vh;

  border-radius: calc(unit * 1.5);
}

.dot {
  position: absolute;
  top: 11px;
  right: 9px;

  width: 6px;

  height: 6px;

  border-radius: 50%;
  background-color: var(--ring-main-color);
  box-shadow: 0 0 0 1px var(--tc-navigation-link-background-color);
}

.feedback {
  display: flex;
  overflow: auto;
  flex-direction: column;

  box-sizing: border-box;

  height: 100%;

  padding: calc(unit * 3);
}
