@value unit: var(--ring-unit);

.path {
  display: flex;
  align-items: baseline;
  flex-wrap: nowrap;
  grid-column: start / end;

  min-width: 0;

  margin: 0 calc(unit * -2);
  padding-top: 6px;
  padding-bottom: 6px;

  &::after {
    position: absolute;

    z-index: -1;
    top: 0;
    right: calc(var(--tc-page-padding-inline) * -1 - unit * 2);
    bottom: 0;
    left: calc(var(--tc-page-padding-inline) * -1 - unit * 2);

    content: '';

    grid-column: start / end;
    grid-row: var(--row) / span 1;
  }

  &:hover::after {
    background-color: var(--ring-hover-background-color);
  }
}

.build + .pathRowGroup .path {
  margin-top: calc(unit * 2);

  /* stylelint-disable-next-line selector-max-specificity */
  &::after {
    top: calc(unit * 2);
  }
}

.branch {
  margin-right: unit;

  white-space: nowrap;
}

.triggered {
  display: inline;

  margin-right: unit;
}

.entityPath {
  flex: 1;
}

.deploy {
  display: flex;
  align-items: baseline;

  margin-left: auto;
  padding-left: calc(unit * 2);
}
