@value unit: var(--ring-unit);

.tabs > :global(.ring-tabs-titles) {
  margin: 0;

  box-shadow: unset;
}

.tabContent {
  display: flex;
  flex: 1;
  flex-direction: column;

  height: 100vh;
}

.pipelineTabs {
  margin-right: calc(unit * -3);
  margin-left: calc(unit * -3);
}

.pipelineTabs > :global(.ring-tabs-titles) {
  box-sizing: border-box;
  width: 100%;
  margin-bottom: 0;
  padding-left: calc(unit * 3);
}

.artifactsTabWrapper {
  padding: calc(var(--ring-unit) * 2.5) var(--tc-page-padding-inline) calc(var(--ring-unit) * 2);
}
