@value awaits-color: var(--ring-warning-color);
@value refuse-color: var(--ring-error-color);
@value approved-color: var(--ring-success-color);
@value unit: var(--ring-unit);

.popup {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  justify-content: center;
  gap: 8px;
}

.inline {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
}

.group .approved,
.approved .status {
  color: var(--ring-success-color);
}

.approvalFrame {
  height: auto;
  min-height: 0;
  padding: 4px;
  padding-top: 2px;
  padding-bottom: 2px;

  border-radius: 4px;
}

.group .awaits,
.approvalsLeft,
.awaits .status {
  color: awaits-color;
}

.groupApproved {
  color: approved-color;
}
