@value unit: var(--ring-unit);

.sidebar {
  z-index: var(--ring-alert-z-index);

  width: 100%;
  height: 100%;
  min-height: 100%;

  background-color: var(--ring-content-background-color);
}

.parameterActions > * {
  padding: 0;

  transition: opacity var(--ring-ease);

  opacity: 1;
}

.content {
  min-height: calc(100% - calc(unit * 8));

  & .textInfo {
    padding: calc(unit * 1.5) 0 0 calc(unit * 2);
  }
}

.continater {
  padding: calc(unit * 2) calc(unit * 2.5);
}

.addParameterButton {
  font-size: var(--ring-font-size-smaller);
}

.parameters {
  padding: calc(unit * 1.5) 0 unit;
}

.file {
  display: flex;
  align-items: center;
  flex-direction: row;
  column-gap: unit;

  &:hover .parameterActions > * {
    opacity: 1;
  }
}

.actions {
  display: flex;
  align-items: center;
  flex-direction: row;
  column-gap: calc(1.5 * unit);

  padding-bottom: calc(unit / 2);
}

.trash {
  padding-top: calc(unit / 4);
}

.notice {
  margin-top: calc(unit * 3 / 4);

  color: var(--ring-secondary-color);

  font-size: var(--ring-font-size-smaller);
  line-height: var(--ring-line-height-lowest);
}

.fileDeleted {
  padding: calc(unit / 4) 0 calc(unit / 1.1);

  text-decoration-line: line-through;

  color: var(--ring-secondary-color);
  -webkit-text-fill-color: var(--ring-secondary-color);

  & .actions {
    padding-bottom: 0;
  }
}

.formNote {
  padding-bottom: calc(unit / 2);

  color: var(--ring-secondary-color);

  font-size: var(--ring-font-size-smaller);
}

.fileAndCheckboxes {
  display: flex;
  flex-direction: column;

  margin-bottom: calc(unit * 2);
}

.checkboxRow {
  display: flex;
  flex-direction: row;
  gap: calc(unit * 3 / 2);

  margin-top: calc(unit / 4);
}
