@value unit: var(--ring-unit);

.lastRunWrapper {
  display: flex;

  margin: 0 calc(var(--tc-page-padding-inline) * -1) calc(unit * 1.5);
  padding: calc(unit * 2.5) var(--tc-page-padding-inline) calc(unit * 2.5)
    calc(var(--tc-page-padding-inline) + unit);

  background-color: var(--ring-secondary-background-color);
}

.lastRunTitle.lastRunTitle {
  margin: 0;
  padding: 0;

  font-size: var(--ring-font-size);
  line-height: var(--ring-line-height);
}

.lastRun {
  max-width: 100%;
}

.lastRunChart {
  margin: 0 0 0 calc(unit * -1);
}
