.activeLink {
  text-decoration-line: none;

  color: var(--ring-text-color);
}

.link {
  display: flex;
  overflow: hidden;
  align-items: baseline;
}

.content {
  overflow: hidden;

  flex: 1 1 auto;

  text-overflow: ellipsis;
}

.contentOffset {
  padding-left: calc(var(--ring-unit) / 2);
}

.tail {
  flex: 0 0 auto;

  padding-right: 8px;

  padding-left: 8px;

  color: var(--ring-secondary-color);

  font-weight: normal;
}

.link.activeLink:hover {
  color: inherit;
  text-decoration-line: none;
}
