@value unit: var(--ring-unit);

.wrapper :global(.ring-dropdown-dropdown) {
  display: block;
}

.popup {
  overflow: hidden;

  padding: calc(unit * 1.5) calc(unit * 2) calc(unit * 2);
}

.popup .heading {
  margin-bottom: unit;
}

.headingLink {
  color: var(--ring-text-color);
}

.statusRow {
  display: flex;
  overflow: hidden;
  flex-direction: column;

  margin-bottom: calc(unit * 1.5);

  &:last-child {
    margin-bottom: 0;
  }
}

.statusRowHeading {
  margin-bottom: calc(unit / 2);
}

.buildPath {
  display: flex;
  align-items: baseline;

  margin-bottom: calc(unit / 2);

  white-space: nowrap;

  &:last-child {
    margin-bottom: 0;
  }
}

.entityPathLink {
  color: var(--ring-link-color);
}

.separator {
  margin-right: 1px;

  color: var(--ring-secondary-color);
}

.showAllButton {
  padding: 0;

  color: var(--ring-secondary-color);
}
