.topbar {
  display: flex;
  align-items: baseline;
  gap: var(--ring-unit);

  margin: 10px 0;

  padding-bottom: 10px;

  border-bottom: 1px solid var(--ring-line-color);
}

.metricsLink {
  margin-left: auto;
}

.metricsTable {
  display: table;

  table-layout: fixed;
}

.metricDescription {
  display: table-cell;

  font-weight: var(--ring-font-weight-bold);
}

.metricRow {
  display: table-row;
}

.metricRowExperimental {
  opacity: 0.6;
}

.metricRow > th {
  text-align: left;

  background-color: var(--ring-secondary-background-color);
}

.headerTagsValues {
  display: flex;
  justify-content: space-around;

  width: 100%;
}

.metricRow:hover {
  background-color: var(--ring-secondary-background-color);
}

.metricRow > * {
  overflow-y: auto;

  box-sizing: border-box;

  width: 33%;

  padding: 10px;
}

.metric {
  display: flex;
  justify-content: space-between;
}

.metricName {
  display: table-cell;
}

.metricNameTooltip {
  padding: 5px 10px;
}

.metricRecords {
  display: table-cell;

  width: 30%;
}

.metricRecord {
  display: flex;
}

.metricTags {
  overflow-y: auto;

  min-width: 70%;
  padding-right: 10px;
  padding-bottom: 20px;
}

.metricValues {
  padding-right: 5px;
}

.metricValue {
  white-space: nowrap;

  font-weight: var(--ring-font-weight-bold);
}
