@value unit: var(--ring-unit);

.page {
  display: flex;
  align-items: center;

  flex-direction: column;

  & .pageHeading.pageHeading {
    margin-top: calc(unit * 10);

    font-size: calc(unit * 5);

    font-weight: 400;
    line-height: calc(unit * 5 + unit / 2);
  }
}

.card {
  display: flex;

  width: 100%;
  max-width: 920px;
  min-height: 240px;

  margin-top: calc(unit * 5);

  border-radius: 20px;
  background-color: var(--ring-secondary-background-color);
}

.content {
  display: flex;

  flex-direction: column;

  padding: calc(unit * 5) calc(unit * 5 / 2) calc(unit * 5) calc(unit * 5);

  & .heading.heading {
    margin: 0;
    padding: 0;

    font-size: calc(unit * 3);

    font-weight: var(--ring-font-weight-bold);
    line-height: calc(unit * 3 + unit / 2);
  }

  & .description {
    margin: 0;
    margin-top: unit;
  }
}

.buttonWrapper {
  align-self: start;

  margin-top: auto;
}

.button {
  padding: calc(0.5 * unit) calc(1.5 * unit);
}

.previewImage {
  display: flex;
  align-items: end;

  width: 260px;
  height: 260px;

  padding: unit calc(unit * 5) 0 calc(unit * 5 / 2);
}
