@value unit: var(--ring-unit);

.sidebar {
  position: relative;

  display: flex;

  overflow: hidden;
  flex-direction: column;

  min-height: calc(17.5 * unit);

  user-select: none;

  outline: none;
  background-color: var(--ring-sidebar-background-color);
}

.header {
  padding-bottom: calc(unit * 2);
}

.tree {
  flex: 1 1 auto;
}

.loader {
  padding-left: calc(unit * 3.5);

  line-height: calc(unit * 3);

  &:first-child {
    margin-top: 0;
  }
}

.loaderText {
  margin-left: 2px;
}
