@value unit: var(--ring-unit);

.dialog {
  width: 600px;
}

.subtitle {
  margin-bottom: calc(unit * 1.5);

  font-weight: var(--ring-font-weight-bold);
}

.content.content {
  & > div {
    padding-top: 0;
    padding-bottom: unit;
  }
}

.text {
  margin-bottom: calc(unit * 3);
}

.imageContainer {
  overflow: hidden;

  width: 536px;
  height: 308px;

  border: 1px solid var(--ring-line-color);
  border-radius: unit;
}

.image {
  max-width: 100%;
  height: auto;
}

.pager {
  display: flex;
  align-items: center;

  & > .number {
    padding-left: unit;

    color: var(--ring-secondary-color);
  }
}

.link {
  margin-right: unit;
}
