@value ellipsis from '../../../globals.module.css';
@value unit: var(--ring-unit);

.wrapper {
  display: inline-block;

  font-size: var(--ring-font-size-smaller);
}

.dropdown,
.anchor {
  width: 100%;
}

.actionButton {
  margin-right: unit;

  &:last-child {
    margin-right: 0;
  }
}

.wrapper .anchor {
  height: unset;
  padding: 0;

  color: var(--ring-text-color);

  line-height: inherit;

  &:hover,
  &:active {
    color: var(--ring-icon-hover-color);
  }
}

.anchor {
  &.badge:hover,
  &.badge:active {
    color: var(--ring-text-color);
  }
}

.icon.icon {
  padding: 0;

  color: var(--ring-icon-secondary-color);
}

.icon.assignedToMe {
  color: var(--ring-main-color);
}

.icon.fixed {
  color: var(--ring-icon-success-color);
}

.icon.badge {
  height: 12px;
  margin-right: calc(unit / 2);
  padding: calc(unit / 2);

  border-radius: calc(unit * 0.75);
  background-color: var(--ring-tag-background-color);

  & > svg {
    vertical-align: initial;
  }
}

.anchor:hover .icon,
.anchor:active .icon {
  color: var(--ring-icon-hover-color);
}

.popup {
  display: flex;
  overflow: hidden;

  width: calc(unit * 50);

  & > div {
    width: 100%;
  }
}

.state {
  word-break: break-word;
}

.timestamp {
  white-space: nowrap;
}

.assignAction {
  display: flex;
  align-items: center;

  height: unset;
  padding: 0;

  color: var(--ring-secondary-color);

  line-height: var(--ring-line-height);
}

.comment,
.scope {
  margin-top: unit;
}

.comment {
  overflow: hidden;
}

.commentText {
  word-break: break-word;
}

.commentTextLoader {
  display: inline-block;
}

.scope {
  display: flex;
  align-items: baseline;
  flex-direction: row;
}

.scopeTitle {
  margin-right: calc(unit / 2);
}

.scopeList {
  overflow: hidden;
  flex: 1;
}

.entityPath {
  flex: 1;

  line-height: var(--ring-line-height);
}

.entityPath .entityPathLink {
  color: var(--ring-link-color);
}

.anchorContent {
  display: flex;
  align-items: baseline;
}

.anchorText {
  composes: ellipsis;

  display: inline-block;

  width: 100%;
  margin-left: calc(unit / 2);
}

.anchorChevron {
  margin-left: 1px;
}

.anchorChevron.anchorChevron svg {
  vertical-align: -3px;
}

.investigationDetails {
  margin: 0 calc(unit * -2) unit;
  padding: 0 calc(unit * 2) unit;
}

.investigationDetails:last-child {
  margin-bottom: 0;
  padding-bottom: 0;
}

.withSeveralInvestigations .investigationDetails {
  margin-bottom: calc(unit * 2);
  padding-bottom: calc(unit * 2);
}

.withSeveralInvestigations .investigationDetails:last-child {
  margin-bottom: 0;
}

.body {
  display: flex;
  flex-direction: column;

  height: 100%;
}

.content {
  overflow-y: auto;

  height: 100%;
  max-height: 400px;
  padding: calc(unit * 1.5) calc(unit * 2) calc(unit * 2);
}

.withSeveralInvestigations .content {
  padding-top: calc(unit * 2);
}

.hasPermission .content {
  padding-bottom: 0;
}

.footer {
  padding: calc(unit * 2);
}

.assigneeName.highlight {
  font-weight: var(--ring-font-weight-bold);
}

.emptyText.badge {
  margin-left: calc(unit / 2);

  color: var(--ring-link-color);
}

.badgeContainer {
  flex-shrink: 0;

  min-width: calc(unit * 16);
  max-width: calc(unit * 25);
}

.label {
  margin-bottom: calc(unit * 0.75);
}

.badge {
  display: inline-flex;

  text-align: left;

  .anchorContent {
    width: 100%;
  }

  .anchorText {
    width: auto;
  }
}
