@value unit: var(--ring-unit);

.overview {
  margin-top: calc(unit * 1.5);
}

.entry {
  display: flex;

  margin-top: unit;

  line-height: var(--ring-line-height);
}

.toolbar {
  margin-left: auto;
}

.labels {
  display: flex;
  flex-wrap: wrap;
}

.title {
  flex-shrink: 0;

  width: calc(unit * 15);

  font-weight: bold;
}

.navigation {
  position: sticky;
  z-index: 5;
  top: 0;

  display: flex;
  align-items: baseline;

  transition: all ease-out 0.1s;

  background-color: var(--ring-content-background-color);

  &.stuck {
    padding: unit 0;
  }
}

.header.header {
  margin-top: 0;
  padding-top: 0;

  padding-left: unit;
}

.readonlyNote {
  margin-left: calc(unit / 2);

  color: var(--ring-secondary-color);
}

.infoIcon {
  margin-left: calc(unit);
}

.readonlyTooltipPopup {
  z-index: 11;
}

.source {
  width: 100%;
  margin-top: calc(unit * 2);
}

.sourceHeader {
  position: sticky;
  z-index: 5;

  top: calc(unit * 4.5);

  display: flex;
  align-items: baseline;
  justify-content: space-between;

  padding: calc(unit * 2) 0 unit;

  background-color: var(--ring-content-background-color);

  & .title {
    width: calc(unit * 35);
  }
}

.code {
  margin-top: unit;

  background-color: var(--ring-secondary-background-color);
}

.copy {
  color: var(--ring-action-link-color);
}

.error {
  margin-top: unit;

  color: var(--ring-error-color);
}
