.container {
  position: relative;

  display: flex;
  align-items: flex-start;
  gap: calc(var(--ring-unit) * 1.5);
}

.checkmark {
  flex-shrink: 0;

  margin-top: calc(var(--ring-unit) * 0.5);

  color: var(--ring-secondary-color);
}

.content {
  display: flex;
  flex: 1;
  flex-direction: column;
  gap: var(--ring-unit);
}

.title {
  margin: 0;

  color: var(--ring-text-color);

  font-size: var(--ring-font-size-larger);
  font-weight: 600;
  line-height: 1.4;
}

.text {
  margin: 0;

  color: var(--ring-secondary-color);

  font-size: var(--ring-font-size);
  line-height: 1.5;
}

.signUpButton {
  align-self: flex-start;

  margin-top: calc(var(--ring-unit) * 0.5);
}

.iconButtonClose {
  position: absolute;

  top: var(--ring-unit);
  right: var(--ring-unit);
}
