@value breakpoint-middle from '../../../../globals.module.css';
@value breakpointMiddle: breakpoint-middle;
@value breakpointLargest: 1600px;
@value build from '../Build/Build.module.css';
@value unit: var(--ring-unit);

.buildContainer {
  --button-offset: var(--tc-page-padding-inline);

  composes: hoverableWrapper from '../Build/BuildCheckbox/BuildCheckbox.module.css';
  composes: wrapper from '../../../common/StarBuild/StarBuild.module.css';

  display: contents;
}

.wrapped {
  --button-offset: calc(unit * 2);
}

.container {
  display: contents;
}

.wrappedContainer {
  composes: wrappedContainer from '../Build/Build.module.css';
}

.open {
  &::before {
    position: absolute;
    top: var(--absolute-child-top);
    right: calc(var(--button-offset) * -1);
    bottom: 1px;
    left: calc(var(--button-offset) * -1);

    content: '';
    pointer-events: none;

    background: var(--ring-content-background-color);

    box-shadow:
      0 0 0 1px var(--ring-line-color),
      0 2px 16px var(--ring-popup-shadow-color);
    grid-column: start / end;
    grid-row: var(--row) / span 4;
  }

  &.wrapped {
    --button-offset: calc(var(--tc-page-padding-inline) + unit * 2);
  }

  &.nested {
    --button-offset: calc(unit * 4);

    &::before {
      border-radius: var(--ring-border-radius);
    }
  }

  & ul {
    margin: 0;
  }

  & :global(.summaryContainer) {
    padding: 0;
  }

  & ul li {
    padding: 0;

    line-height: var(--ring-line-height-lower);

    &:not(:first-child) {
      margin-top: calc(unit * 3 - var(--ring-line-height-lower));
    }
  }

  /* stylelint-disable-next-line selector-max-specificity */
  & td:nth-last-child(2) ul:global(.bsLinks) {
    width: 10vw;
    min-width: calc(0.1 * breakpointMiddle);
    max-width: calc(0.1 * breakpointLargest);
  }

  & :global(.header) {
    margin: 0;
    padding: 0;

    background: transparent;
  }

  /* stylelint-disable-next-line selector-max-specificity */
  & td:first-child > :global(.header) {
    display: none;
  }
}

.heading {
  display: contents;

  cursor: pointer;
}

.button {
  composes: beforeWrapper from '../../../common/StarBuild/StarBuild.module.css';

  content: '';

  grid-column: start / end;
  grid-row: var(--row) / span 3;
}

.button.button {
  top: calc(var(--absolute-child-top) - 1px);
  right: calc(var(--button-offset) * -1);
  left: calc(var(--button-offset) * -1);

  width: calc(100% + var(--button-offset) * 2);
}

.wrapped .button {
  top: var(--absolute-child-top);
  bottom: 1px;
}

.detailsWrapper {
  min-width: 0;
  margin: 0 calc(var(--tc-page-padding-inline) * -1);
  padding: 0 var(--tc-page-padding-inline);
  grid-column: start / end;
}

.wrapped .detailsWrapper {
  margin: 0 calc(unit * -2);
  padding: 0 calc(unit * 2);
}

.queued .button,
.queued .detailsWrapper {
  background-color: var(--ring-secondary-background-color);
}

.button:focus {
  outline: none;
  box-shadow: inset 2px 0 var(--ring-main-color);
}

.nested.open .button {
  border-top-left-radius: var(--ring-border-radius);
  border-top-right-radius: var(--ring-border-radius);
}

/* stylelint-disable selector-max-specificity */
.closed:hover .button,
.closed .button:focus {
  background-color: var(--ring-hover-background-color);
}

.wrappedContainer:first-child .button,
.wrappedContainer:first-child .open::before {
  border-top-left-radius: var(--ring-border-radius-small);
  border-top-right-radius: var(--ring-border-radius-small);
}

.withQueued .wrappedContainer:first-child .button,
.withQueued .wrappedContainer:first-child .open::before {
  border-top-left-radius: 0;
  border-top-right-radius: 0;
}

/* stylelint-disable-next-line no-descending-specificity */
.wrappedContainer:last-child .open::before,
.wrappedContainer:last-child .buildContainer:not(.open) .button {
  border-bottom-right-radius: var(--ring-border-radius-small);
  border-bottom-left-radius: var(--ring-border-radius-small);
}
/* stylelint-enable */

.arrow {
  position: absolute;

  grid-column: -2;
  grid-row: var(--row) / span 3;

  top: calc(50% - 11px + var(--absolute-child-top));
  right: -17px;
  left: auto;

  padding: 0;

  color: transparent;

  line-height: normal;

  .buildContainer:hover &,
  .button:focus ~ & {
    color: var(--ring-link-hover-color);
  }

  .buildContainer.open & {
    color: var(--ring-icon-secondary-color);
  }

  /* stylelint-disable-next-line selector-max-specificity */
  .buildContainer.open .heading:hover & {
    color: var(--ring-link-hover-color);
  }
}

.content {
  overflow: hidden;

  width: 100%;

  margin: 0 calc(var(--tc-page-padding-inline) * -1);
  padding: 0 var(--tc-page-padding-inline);
}

.tabs {
  overflow: hidden;

  margin: -1px calc(unit * -2) calc(unit * 2);
  padding: 8px calc(unit * 2) 9px;

  background-color: var(--ring-secondary-background-color);

  font-size: var(--ring-font-size-smaller);

  line-height: var(--ring-line-height-lowest);
}

.nested .tabs {
  margin-right: calc(unit * -4);
  margin-left: calc(unit * -4);
}

.separator {
  position: relative;
  z-index: 1;

  margin: -1px calc(unit * -2) 0;

  border-top: 1px solid var(--ring-line-color);
}

.loader {
  margin-bottom: calc(unit * 3);
}

.loaderPlaceholder {
  composes: loader;

  visibility: hidden;
}

.snapshotDependenciesChart {
  width: 40%;
}

@media (width <= 1200px) {
  .snapshotDependenciesChart {
    width: 60%;
  }
}

.queueInfoTitle {
  font-size: var(--ring-font-size);
}

.queueInfoWrapper {
  display: flex;

  flex-wrap: wrap;

  font-size: var(--ring-font-size);

  line-height: var(--ring-line-height) !important;

  & .queueInfo {
    margin-right: calc(unit * 1.5);
  }
}

.customizedBuildNote {
  margin-bottom: calc(unit * 1.5);
}

.secondInfoGroup .row {
  margin-bottom: unit;

  &:last-child {
    margin-bottom: calc(unit * 4);
  }
}

.open :global(.buildResultsSummaryTable) {
  width: 100%;

  & > tbody > tr > td {
    padding: unit 0 calc(unit * 3) !important;

    /* stylelint-disable-next-line selector-max-specificity */
    &:nth-child(2) {
      width: 100%;
      max-width: 0;

      padding-left: calc(unit + 1px) !important;

      box-shadow: inset 0 1px var(--ring-line-color);
    }
  }
}

.emptyRow {
  grid-column: start / end;
}

.outerContainer {
  position: relative;
}

.innerContainer {
  position: absolute;
  top: 0;
  right: 0;
  left: 0;
}

.runContent {
  padding-top: calc(unit * 1.5);
}
