@value unit: var(--ring-unit);

.main {
  display: flex;

  align-items: center;

  margin-bottom: calc(unit / 2);

  padding-right: calc(unit * 8);
}

.icon {
  display: flex;
  align-items: center;
  justify-content: center;

  width: calc(unit * 4);
  height: calc(unit * 4);

  margin-right: unit;

  cursor: pointer;

  text-align: center;

  color: var(--ring-icon-color);

  border-radius: unit;
  background-color: var(--ring-tag-background-color);

  & svg {
    fill: currentColor;
  }
}

.labelWrapper {
  display: flex;
  flex: 1;

  min-width: 0;
}

.label {
  overflow: hidden;

  white-space: nowrap;

  text-overflow: ellipsis;

  color: var(--ring-text-color);
}
