@value unit: var(--ring-unit);

.triggerActions {
  margin-top: -1px;

  grid-area: actions;
}

.triggerActions > * {
  transition: opacity var(--ring-ease);

  opacity: 0;
}

.trigger {
  position: relative;

  display: grid;

  align-items: baseline;

  justify-content: space-between;

  margin-bottom: unit;

  padding: unit;

  border-radius: calc(unit * 1.5);
  background-color: var(--ring-secondary-background-color);
  grid-template-areas: 'label toggle' 'label actions';
  gap: calc(unit / 2);

  &:hover .triggerActions > * {
    opacity: 1;
  }
}

.triggerToggle {
  grid-area: toggle;

  justify-content: end;
}

.triggerToggle span:first-child {
  flex-shrink: 0;
}

.triggerDetail {
  margin-top: calc(unit / 2);

  transition: all 300ms ease-in-out;

  color: var(--ring-secondary-color);

  font-size: var(--ring-font-size-smaller);
  line-height: var(--ring-line-height-lowest);
}

.triggerDetailDisabled {
  opacity: 0.4;
}

.triggerLabel {
  grid-area: label;
}

.errorMessage {
  padding-top: calc(unit * 0.3);

  color: var(--ring-error-color);

  font-size: var(--ring-font-size-smaller);
}
