@value font-smaller-lower from '../../../../globals.module.css';
@value unit: var(--ring-unit);

.wrapper {
  composes: font-smaller-lower;

  display: flex;
  align-items: baseline;

  max-width: 900px;
}

.header {
  display: flex;
}

.timestamp {
  color: var(--ring-secondary-color);
}

.userInfo {
  margin-right: calc(unit / 2);
}

.button {
  padding-right: unit;
  padding-left: 0;

  color: var(--ring-secondary-color);
}

.icon {
  flex: 0 0 auto;

  margin-right: calc(unit / 2);

  color: var(--ring-icon-secondary-color);
}
