@value unit: var(--ring-unit);

.list {
  display: flex;
  flex-wrap: nowrap;
}

.tagsContainer {
  display: flex;
  flex-wrap: nowrap;
}

.list button {
  overflow: hidden;

  max-width: calc(unit * 19);

  cursor: default;
  text-overflow: ellipsis;
}

.list button:hover {
  background-color: var(--ring-tag-background-color);
}

.more {
  cursor: default;
}
