@value unit: var(--ring-unit);

.tree {
  position: relative;

  z-index: 0;

  margin-top: calc(unit * 2);

  padding: calc(unit * 1.5) calc(unit * 2);

  border: 1px solid var(--ring-line-color);
  border-radius: 3px;
}

.expandAllButton,
.investigationMuteButtons {
  margin-right: unit;
}

.investigationMuteButtons {
  margin-left: unit;
}
