@value unit: var(--ring-unit);

.wrapper {
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.svgContainer {
  max-width: calc(unit * 70);

  margin: 0 auto;

  text-align: center;

  &.defaultUi {
    padding-top: calc(unit * 17.5);

    & > svg {
      margin-top: calc(unit * 8.5);
    }
  }
}

.infoContainer {
  max-width: calc(unit * 40);
  height: calc(unit * 30);

  margin: 0 auto;

  text-align: center;
}

.description {
  padding: 0 calc(unit * 2);
}

.benefits {
  margin-bottom: unit;
}
