@value nodes from '../../../../common/Tree/Tree.module.css';
@value item, label from '../../../../common/Tree/TreeNode/TreeNode.module.css';
@value unit: var(--ring-unit);

.filterItem {
  margin-right: calc(unit * 2);
  margin-bottom: calc(unit * 2);
}

.emptyList {
  color: var(--ring-secondary-color);
}

.grid {
  padding: 0 calc(unit * 2);
}

.tree .grid {
  margin-right: calc(unit * 2);
  padding-left: 0;
}

.tree {
  margin: 0 calc(var(--tc-page-padding-inline) * -1) 0
    calc(var(--tc-page-padding-inline) * -1 - 2px);
  padding: 0 calc(var(--tc-page-padding-inline) - unit * 2);
}

.tree .item {
  margin-inline: calc(unit * 2 - var(--tc-page-padding-inline));
  padding-inline: calc(var(--tc-page-padding-inline) - unit * 2);
}

.buildType,
.buildType > .item,
.buildType > .item > .label {
  display: contents;
}

.infiniteScroll {
  margin: 0 calc(var(--tc-page-padding-inline) * -1);
  padding: 0 var(--tc-page-padding-inline);
}

.loader {
  padding-top: calc(unit * 2);
}

.loadMoreButtonWrapper {
  display: flex;

  align-items: center;
  flex-direction: column;

  padding-top: calc(unit * 2);
}

.showAllButton {
  color: var(--ring-secondary-color);
}

.row {
  display: contents;
}
