@value unit: var(--ring-unit);

.legend {
  composes: legend from '../../DependenciesTimeline/Legend/Legend.module.css';

  white-space: nowrap;
}

.legend.legend {
  flex-wrap: nowrap;
  justify-content: flex-start;

  margin-top: unit;
  margin-bottom: 0;
}

.marker {
  composes: marker from '../../DependenciesTimeline/Legend/Legend.module.css';
}

.marker.marker {
  --size: 14px;

  vertical-align: -2px;
}

.run {
  margin-right: calc(unit * 0.5);

  color: var(--ring-icon-color);
}

.unrelated {
  composes: marker;

  margin: 0 5px 0 1px;

  border: 1.5px dashed var(--ring-borders-color);
}

.circle {
  composes: marker;

  box-shadow: 0 0 0 1.5px var(--ring-borders-color) inset;
}

.stack {
  composes: stack from '../DependenciesChain.module.css';

  &::before {
    display: none;
  }
}

.selected {
  --offset: calc(unit * 0.5);

  composes: circle;

  position: relative;

  &::before {
    position: absolute;
    top: calc(var(--offset) * -1);
    right: calc(var(--offset) * -1);
    bottom: calc(var(--offset) * -1);
    left: calc(var(--offset) * -1);

    content: '';

    border: 2px solid var(--ring-main-color);

    border-radius: 50%;
  }
}

.reused {
  --offset: 5px;

  composes: circle;

  position: relative;

  &::before {
    position: absolute;
    top: calc(var(--offset) * -1);
    right: calc(var(--offset) * -1);
    bottom: calc(var(--offset) * -1);
    left: calc(var(--offset) * -1);

    content: '';

    border-radius: 50%;

    background-color: rgba(237, 162, 0, 0.3);
  }
}

.marker.selected,
.marker.reused {
  margin: 0 calc(unit * 0.5 + var(--offset)) 0 var(--offset);
}
