@value unit: var(--ring-unit);

.wrapper {
  position: relative;

  display: flex;

  overflow: hidden;
  flex-direction: row;

  justify-content: space-between;

  width: 100%;
}

.title {
  overflow: hidden;

  cursor: pointer;

  letter-spacing: 2px;
  text-overflow: ellipsis;

  font-size: var(--ring-font-size-smaller);
  font-weight: var(--ring-font-weight-bold);

  line-height: calc(var(--ring-unit) * 3);
}

.popup {
  padding: unit;
}

.popupHeader {
  margin-top: calc(2 * unit);

  font-size: calc(3 * unit);
}
