@value font from '../../../globals.module.css';
@value unit: var(--ring-unit);

.listItem {
  composes: font;

  position: relative;

  box-sizing: border-box;

  margin: 1px calc(var(--tc-page-padding-inline) * -1) 0;
  padding: 0 calc(var(--tc-page-padding-inline) + unit);

  line-height: calc(unit * 3);

  &::before {
    position: absolute;
    z-index: -2;
    top: -1px;
    right: 0;
    bottom: -1px;
    left: 0;

    content: '';

    opacity: 0;
    background-color: var(--ring-hover-background-color);
  }
}

.focusableWrapper:focus {
  outline: none;
}

/* stylelint-disable selector-max-specificity */
.focusableWrapper:focus .listItem::before,
.focusableWrapper:focus + .listItem::before {
  opacity: 1;
  background-color: transparent;
  box-shadow: inset 2px 0 var(--ring-main-color);
}

.highlightHover:hover::before,
.focusableWrapper:focus .highlightHover::before,
.focusableWrapper:focus + .highlightHover::before {
  opacity: 1;
  background-color: var(--ring-hover-background-color);
}
/* stylelint-enable */

.row {
  align-items: baseline;
  flex-wrap: nowrap;

  padding-bottom: 10px;

  box-shadow:
    0 1px var(--ring-line-color),
    0 -1px var(--ring-line-color);
}

.hideTopBorder .row {
  box-shadow: 0 1px var(--ring-line-color);
}

.hideBorders {
  margin-top: 0;

  & .row {
    box-shadow: none;
  }

  &::before {
    top: 0;
    bottom: 0;
  }
}

.row > * {
  box-sizing: border-box;
  margin: 6px 0 0;
  padding: 0 unit;
}

.row > :first-child {
  padding-left: 0;
}

.row > :last-child {
  padding-right: 0;
}
