@value unit: var(--ring-unit);

.anchor {
  display: flex;
}

.icon {
  display: block;
}

.name {
  white-space: nowrap;
}

.icon,
.name {
  margin-right: unit;
}

.transformedComment {
  overflow: hidden;
  flex-shrink: 1;

  white-space: nowrap;

  text-overflow: ellipsis;
}

.transformedComment br {
  display: inline;
  clear: none;

  content: ' ';
}

.popup {
  max-width: calc(40 * unit);
  padding: unit;
}
