@value font-smaller from '../../../../globals.module.css';
@value exactDuration, exactStarted from '../../BuildDuration/BuildDurationAnchor/BuildDurationAnchor.module.css';

.buildsHeader {
  composes: font-smaller;

  display: contents;

  & > * {
    margin-bottom: var(--ring-unit);
  }

  color: var(--ring-secondary-color);
}

.oneLine {
  composes: oneLine from '../Build/Build.module.css';
}

.number {
  composes: number from '../Build/Build.module.css';
}

.branch {
  composes: branchPath from '../Build/Build.module.css';

  box-sizing: border-box;
}

.status {
  grid-column-start: status-start;
}

.changes {
  composes: changes from '../Build/Build.module.css';
}

.agent {
  composes: agent from '../Build/Build.module.css';
}

.durationWrapper {
  composes: duration from '../Build/Build.module.css';

  display: flex;
  align-items: baseline;
  justify-content: flex-end;
}

.started {
  composes: exactStarted;
}

.duration {
  composes: exactDuration;

  text-align: end;
}

.icons {
  composes: icons from '../Build/Build.module.css';
}
