@value font-smaller-lower from '../../../globals.module.css';
@value default-branch-background-color: var(--tc-default-branch-background-color);
@value default-branch-background-hover-color: var(--tc-default-branch-background-hover-color);
@value unit: var(--ring-unit);

:root {
  --tc-default-branch-background-color: #8ccbff;
  --tc-default-branch-background-hover-color: #2e436e;
}

:global(.ring-ui-theme-dark),
:global(.ring-variables_dark-dark) {
  --tc-default-branch-background-color: #0d5087;
  --tc-default-branch-background-hover-color: #212d45;
}

.buildBranch {
  display: inline-block;

  box-sizing: border-box;
  max-width: 100%;
  height: 20px;

  user-select: text;
  transition:
    color var(--ring-fast-ease),
    background-color var(--ring-fast-ease),
    box-shadow var(--ring-fast-ease);
  white-space: nowrap;

  color: var(--ring-text-color);

  border-radius: var(--ring-border-radius);
  background-color: var(--ring-hover-background-color);

  font-size: var(--ring-font-size-smaller);
  font-weight: normal;
  line-height: var(--ring-line-height);
  padding-inline: unit;
}

.low {
  composes: font-smaller-lower;
}

.buildBranchContent {
  position: relative;

  display: inline-flex;

  width: 100%;
}

.copyIconWrapper {
  position: absolute;
  top: 0;
  right: calc(unit * -1);

  width: calc(unit * 3);
  height: calc(100% - 1px);
  padding-top: 1px;

  padding-right: calc(unit / 4);

  transition: opacity var(--ring-fast-ease);

  text-align: right;

  opacity: 0;

  color: var(--ring-icon-color);

  border-radius: 0 var(--ring-border-radius) var(--ring-border-radius) 0;

  background: linear-gradient(90deg, transparent, var(--ring-selected-background-color) 25%);

  &:hover {
    & svg {
      color: var(--ring-link-hover-color);
    }
  }
}

.buildBranch.link,
.buildBranch.link:hover {
  color: var(--ring-text-color);
}

.autoTrim {
  max-width: 100%;
}

.defaultTrim {
  max-width: calc(unit * 23);
}

.withBorder {
  box-shadow: 0 0 0 1px var(--ring-borders-color) inset;
}

.withIcon {
  color: var(--ring-text-color);
}

.main {
  background-color: default-branch-background-color;
}

.main,
.link:hover,
.link:focus {
  box-shadow: none;

  & *::selection {
    background-color: default-branch-background-hover-color;
  }
}

.icon {
  margin-right: calc(unit / 8);

  user-select: auto;
}

.inline {
  padding: 0;

  color: var(--ring-link-color);

  background-color: transparent;

  & .icon {
    margin-right: calc(unit / 2);

    color: var(--ring-icon-color);
  }
}

.inline.link:hover,
.inline.link:focus {
  color: var(--ring-link-hover-color);

  background-color: transparent;
}

.copyIcon {
  margin-right: 0;
  margin-left: calc(unit / 2);

  &:hover {
    & svg {
      color: var(--ring-link-hover-color);
    }
  }
}

.link:focus,
.link:hover:hover {
  outline: none;
  background-color: var(--ring-selected-background-color);
}

.buildBranch:hover .copyIconWrapper {
  opacity: 1;
}

.link:hover .innerLink,
.link:focus .innerLink {
  border-bottom-width: 0;
}

.tooltipWrapper {
  display: block;
  overflow: hidden;

  max-width: calc(100% - 1px);
  height: 24px;
}
