@value focusableWrapper from '../../../common/ListItem/ListItem.module.css';
@value link from '../../../common/BuildNumber/BuildNumber.module.css';
@value unit: var(--ring-unit);

.panel {
  z-index: 1;

  margin: 1px calc(var(--tc-page-padding-inline) * -1) 0;
  padding: 0 var(--tc-page-padding-inline) calc(unit * 2);

  box-shadow:
    0 0 0 1px var(--ring-line-color),
    0 2px 8px var(--ring-popup-shadow-color);
}

.button {
  composes: focusableWrapper;
}

.item {
  composes: focusableWrapper;

  position: relative;

  display: block;

  margin: 1px calc(var(--tc-page-padding-inline) * -1) 0;
}

.row {
  display: flex;
  align-items: baseline;
  flex-direction: row;

  padding: 0;

  & > * {
    margin-top: 0;
  }
}

.arrow {
  position: absolute;

  top: 5px;
  right: calc(unit * -4 + 10px);
  left: auto;

  padding: 0;

  transition: opacity var(--ring-fast-ease);

  pointer-events: none;

  opacity: 0;
  color: var(--ring-icon-secondary-color);

  line-height: normal;

  &.advancedRowArrow {
    top: 8px;
  }
}

.smallPadding {
  &.panel {
    margin: 1px calc(unit * -2) 0;
    padding: 0 calc(unit * 2) calc(unit * 2);
  }

  & .item {
    margin: 1px calc(unit * -2) 0;
    padding: 0 calc(unit * 3);
  }

  & .arrow {
    right: calc(unit * -4.5);
  }
}

.item:hover ~ .arrow,
.button:focus ~ .arrow {
  transition: none;

  opacity: 1;
}

.button:active ~ .arrow {
  transition: none;

  opacity: 1;
  color: var(--ring-main-color);
}

.defaultRow {
  line-height: 24px;

  &::before {
    height: 24px;
  }
}

.advancedRow {
  min-height: 31px;

  &::before {
    top: 0;
    right: 0;
    bottom: 0;
    left: 0;
  }

  & .row {
    padding-bottom: 6px;

    line-height: var(--ring-line-height);

    & > * {
      margin-top: 5px;
    }
  }
}

.pathCol {
  display: flex;
  overflow: hidden;
  align-items: baseline;
  flex: 1 1 auto;
}

.entityPath {
  white-space: nowrap;
}

.filesCol {
  display: flex;
  flex: 0 0 auto;
  justify-content: flex-end;

  width: calc(unit * 7);

  text-align: right;

  white-space: nowrap;

  font-size: var(--ring-font-size-smaller);
}

.pathCol,
.filesCol {
  padding-left: 0;
}

.expandableLines {
  & .filesCol {
    width: 70px;
  }
}

.separator {
  flex-shrink: 0;

  color: var(--ring-secondary-color);
}

.buildNumber {
  margin-right: unit;
}

.buildNumber .link {
  color: var(--ring-text-color);

  font-size: var(--ring-font-size);
}
