@value unit: var(--ring-unit);

.card {
  display: flex;
  flex-direction: column;

  box-sizing: border-box;

  width: 274px;
  height: 128px;
  padding: calc(unit * 2);

  cursor: pointer;

  text-align: left;

  border: 1px solid;
  border-radius: unit;
  background: none;

  font-family: inherit;
  font-size: inherit;
  gap: unit;
}

.cardActive {
  border-color: var(--ring-main-color);
  background-color: var(--ring-hover-background-color);
}

.cardInactive {
  border-color: var(--ring-line-color);
  background-color: var(--ring-content-background-color);
}

.cardIcon {
  svg {
    width: 32px;
    height: 32px;
  }

  width: 32px;
  height: 32px;

  color: var(--ring-icon-color);
}

.iconAndTag {
  display: flex;
  align-items: center;
  justify-content: space-between;

  width: 100%;
}

.cardContent {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
