@value font-smaller from '../../../globals.module.css';
@value unit: var(--ring-unit);

.buildNumber {
  composes: font-smaller;
  composes: wrapper from '../StarBuild/StarBuild.module.css';
  composes: link from '../LinkWithIcon/LinkWithIcon.module.css';

  position: relative;

  color: var(--ring-text-color);
}

.myPersonal {
  font-weight: var(--ring-font-weight-bold);
}

.personal,
.canceled {
  color: var(--ring-secondary-color);
}

.canceled,
.canceled:hover {
  text-decoration-line: line-through;
}

.text {
  composes: text from '../LinkWithIcon/LinkWithIcon.module.css';
}

.starIcon {
  padding: 0 calc(unit / 2);
}

.numberWithComment {
  min-width: 0;
}

.comment,
.warning {
  margin-left: calc(unit / 2);
}

.link {
  width: 100%;
  min-width: 0;
}

.moveToTop.moveToTop {
  margin-left: calc(unit * -1);
  padding-right: 3px;
}
