@value unit: var(--ring-unit);

.controls {
  display: flex;

  column-gap: unit;
  row-gap: unit;
}

.controlsButton {
  display: flex;

  column-gap: unit;
}

.foldButton {
  display: flex;

  & span {
    align-self: center;

    padding-top: 1px;
  }
}

.searchContainer {
  flex: 1;
}

.search::-webkit-search-cancel-button {
  -webkit-appearance: none;
}
