.error {
  margin-top: var(--ring-unit);

  color: var(--ring-error-color);
}

.iconButtonClose {
  position: absolute;

  top: var(--ring-unit);
  right: var(--ring-unit);
}

.image {
  display: flex;
  align-items: center;
  flex-grow: 1;
  justify-content: center;
}

.success {
  position: relative;

  display: flex;
  align-items: center;
}

.checkmark {
  margin-right: calc(var(--ring-unit) * 1.5);

  color: var(--ring-secondary-color);
}
