@value unit: var(--ring-unit);

.section {
  display: flex;
  flex-direction: column;
  flex-grow: 1;
}

.hint {
  display: block;

  margin: 0;
  padding: 0;
}

.textareaContainer {
  flex-grow: 1;

  width: 100%;
  margin-top: calc(unit / 2);

  resize: none;
}

.textareaContainer :global(.ring-input-container),
.textarea {
  display: block;

  height: 100%;
}
