@value unit: var(--ring-unit);

.header .heading {
  overflow: hidden;

  margin: 0;
  margin-bottom: calc(unit * 2);

  word-break: break-word;

  &::first-letter {
    text-transform: uppercase;
  }
}

.filter {
  margin-bottom: calc(unit * 2);
}

.changeDetailsTabs {
  padding-bottom: calc(unit * 4);
}
