@value ellipsis from '../../../../../globals.module.css';
@value unit: var(--ring-unit);

.header {
  z-index: 3;

  display: grid;
  overflow: hidden;

  align-items: start;

  box-sizing: border-box;

  margin: calc(unit * -2) calc(var(--tc-page-padding-inline) * -1) 0;
  padding: calc(unit * 2) var(--tc-page-padding-inline);

  background-color: var(--ring-content-background-color);

  grid-gap: calc(unit * 1.5);
  grid-template-columns: 1fr max-content;
  grid-template-rows: auto;
}

.headerBottomLine {
  box-shadow: 0 1px var(--ring-line-color);
}

.heading {
  overflow: hidden;
  align-content: baseline;

  min-height: 28px;
  grid-column: 1;
  grid-row: 1;
}

.title {
  display: flex;
}

.title.title {
  margin: 0;
  padding: 0;
}

.content {
  grid-column: span 2;
  grid-row: 2;

  display: flex;

  column-gap: calc(unit / 2);

  & > div {
    max-width: calc(unit * 50);
  }
}

.actions {
  grid-column: 2;
  grid-row: 1;

  display: flex;
  justify-content: end;
}
