@value font-smaller-lower from '../../../globals.module.css';
@value unit: var(--ring-unit);

.button {
  height: auto;
  padding: 0;

  line-height: inherit;
}

.wrapper {
  composes: font-smaller-lower;

  display: flex;
  align-items: baseline;

  max-width: 100%;
}

.content {
  flex-grow: 1;

  min-width: 0;

  color: var(--ring-text-color);
}

.inlineCommentText {
  flex-grow: 1;

  min-width: 0;

  color: var(--ring-secondary-color);
}

.info {
  white-space: nowrap;

  color: var(--ring-text-color);
}

.user {
  padding: 0 calc(unit / 2);

  white-space: nowrap;

  color: var(--ring-secondary-color);
}

.text {
  min-width: 0;
}
