/* ensure correct styles order */
@import '../ProjectsTree/ProjectsTree.module.css';

@value font-smaller-lower from '../../../globals.module.css';
@value unit: var(--ring-unit);

.dialog {
  width: calc(unit * 66);
  height: calc(100vh - unit * 8);
  max-height: calc(unit * 72);
}

.content {
  flex-grow: 1;

  height: 100%;
}

.treeContent {
  display: flex;
  flex-direction: column;
  flex-grow: 1;

  height: auto;
}

.treeItemParent {
  flex-grow: 1;
}

.scrollableWrapper,
.tree {
  height: 100%;
  padding: 0;
}

.tree {
  padding-right: calc(unit * 2);
  padding-left: calc(unit * 2);
}

.header {
  padding: calc(unit * 4) calc(unit * 4) 0;
}

.shortcuts {
  composes: font-smaller-lower;

  margin: unit calc(unit * 4) calc(unit * 2);

  color: var(--ring-secondary-color);

  font-weight: normal;
}

.search {
  width: 100%;
  margin-right: calc(unit * 4);
}

.searchWrapper {
  box-sizing: border-box;
  width: 100%;
  padding: unit calc(unit * 1.5) 0;
}

.button {
  margin-right: unit;
}

.footer {
  display: flex;
  align-items: baseline;

  width: calc(100% + unit * 4);
  margin-right: calc(unit * -2);
  margin-left: calc(unit * -2);

  box-shadow: inset 0 1px var(--ring-line-color);

  line-height: calc(unit * 3);
}

.resetOrder {
  margin-left: auto;
}

.configureSidebarHint {
  transform: translateX(calc(unit * -2));
}

.iconButton {
  margin-right: calc(unit / 2);
}
