@value unit: var(--ring-unit);

.container {
  display: flex;

  width: 100%;
  height: 100%;
  padding: 6px 0 0;
}

.checkboxGroup {
  display: flex;
  flex-direction: column;
  gap: calc(unit * 0.5);
}

.nestedCheckboxGroup {
  display: flex;
  flex-direction: column;

  margin-top: calc(unit * 0.5);
  margin-left: calc(unit * 2);
  gap: calc(unit * 0.5);
}

.offset {
  margin-left: calc(unit * 3);
}
