@value unit: var(--ring-unit);

.sidebar {
  width: 100%;
  height: 100%;
}

.headerWrapper {
  padding-bottom: calc(unit * 1.5);

  border-bottom: 2px solid var(--ring-secondary-background-color);
}

.editorContainer {
  height: 100%;
  padding: calc(unit * 2) calc(unit * 2.5) calc(unit * 2.5);
}

.emailsSelect {
  width: 100%;
}

.eventsContainer {
  margin-top: calc(unit * 1.5);
}

.eventsSelect {
  width: 100%;
}

.eventButton {
  width: 50%;
}

.branchSpecPolicy {
  padding-left: 1px;
}

.label {
  display: block;

  margin-top: calc(unit * 2);

  margin-bottom: calc(unit / 4);

  color: var(--ring-secondary-color);

  font-size: var(--ring-font-size-smaller);
}
