@value unit: var(--ring-unit);

.dialog {
  composes: dialog from '../../../../components/packages/BuildLog/BuildLogPopup/BuildLogPopup.module.css';
}

.overlay {
  composes: overlay from '../../../../components/packages/BuildLog/BuildLogPopup/BuildLogPopup.module.css';
}

.header {
  display: flex;
  align-items: center;
  gap: calc(unit);

  line-height: calc(unit * 3);
}

.title {
  font-size: calc(unit * 2.5);
}

.summary {
  display: flex;

  min-width: fit-content;

  padding-bottom: unit;

  color: var(--ring-secondary-color);

  font-weight: normal;
  line-height: calc(unit * 2);
}

.vendor {
  color: var(--ring-text-secondary);
}

.verified {
  margin-left: calc(unit / 4);
}

.verified svg {
  vertical-align: -2px !important;
}

.right {
  float: right;
}

.statistics {
  display: flex;

  min-width: fit-content;

  margin-left: calc(unit);
}

.statisticsItem {
  margin-left: calc(unit / 2);

  color: var(--ring-secondary-color);
}

.statisticsValue {
  margin-left: calc(unit / 2);

  color: var(--ring-secondary-color);
}

.container {
  padding-top: calc(unit / 2);
  padding-right: calc(unit * 4);
  padding-left: calc(unit * 4);
}

.codeEditorContainer {
  border-radius: var(--ring-border-radius-large) var(--ring-border-radius-large) 0 0;
  background-color: var(--ring-secondary-background-color);
}

.editorHeader {
  display: flex;
  justify-content: space-between;

  padding: var(--ring-unit) calc(var(--ring-unit) * 2.5);

  border-bottom: 1px solid var(--ring-borders-color);
}

.copy {
  color: var(--ring-action-link-color);
}

.versionListItem {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.versionListItem .badge {
  display: none;
}

.versionListItem.incompatible .badge {
  display: inline;

  padding: 4px 8px;

  color: var(--ring-warning-color);
  border-radius: 4px;
  background-color: var(--ring-warning-background-color);

  font-size: var(--ring-font-size-smaller);
  line-height: 1;
}

.selectButton {
  color: var(--ring-text-color);
}
