@value unit: var(--ring-unit);

.valuesContainer {
  display: flex;
  flex: 1;
  flex-direction: column;

  width: 100%;

  margin-top: calc(unit - unit / 4);
}

.values.values {
  display: flex;
  align-items: center;
  flex-wrap: nowrap;
}

.value {
  display: flex;
  align-items: center;
  flex: 1;
  justify-content: center;

  padding-top: 5px;

  font-family:
    'Twemoji Mozilla', 'Apple Color Emoji', 'Segoe UI Emoji', 'Segoe UI Symbol', 'Noto Color Emoji',
    'EmojiOne Color', 'Android Emoji', sans-serif;
}

.hints {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;

  padding: calc(unit / 4) 0;
}

.hint {
  display: block;

  margin: 0;
  padding: 0;

  color: var(--ring-secondary-color);

  font-size: var(--ring-font-size-smaller);
}

.hint:nth-child(1) {
  text-align: left;
}

.hint:nth-child(2) {
  text-align: center;
}

.hint:nth-child(3) {
  text-align: right;
}

.goBack {
  margin-right: unit;
}
