@value unit: var(--ring-unit);

.header {
  padding: 0 calc(unit * 2);

  border-bottom: 1px solid var(--ring-line-color);

  background-color: var(--ring-content-background-color);

  &.targetPage {
    padding: 0 var(--tc-page-padding-inline);
  }

  &.jobDetailsPopupTarget {
    padding: 0 var(--tc-page-padding-inline) unit;
  }

  &.jobDetailsSidebarTarget,
  &.jobDebugPanelTarget {
    padding: 0 var(--tc-page-padding-inline) calc(unit * 1.5) calc(unit * 2.5);
  }

  &.jobDebugPopupTarget {
    padding: calc(unit * 2) calc(unit * 4) calc(unit * 1.5);
  }
}

.headerTimeline {
  padding-top: calc(unit * 2.5);

  &.targetPage {
    padding-top: calc(unit * 3);
  }
}

.jobDetailsPopupTarget,
.jobDebugPopupTarget {
  & .controls {
    max-width: 1280px;
  }
}
