@value unit: var(--ring-unit);

.actions {
  position: absolute;
  top: unit;
  right: unit;

  display: flex;

  transition: opacity var(--ring-ease);

  opacity: 0;

  gap: calc(unit / 2);
}

.withHeader {
  top: calc(unit * 2);
}

.main {
  position: relative;

  padding: unit;

  border-radius: calc(unit * 1.5);

  background-color: var(--ring-secondary-background-color);

  &:hover .actions {
    opacity: 1;
  }
}

.error {
  margin-top: calc(unit / 2);

  color: var(--ring-error-color);

  font-size: var(--ring-font-size-smaller);
}

.showMoreButton {
  margin-top: calc(unit / 2);

  font-size: var(--ring-font-size-smaller);
}
