@value unit: var(--ring-unit);

.recoveryKeysWithActions {
  display: flex;

  margin: unit 0;
}

.recoveryKeys {
  padding: calc(unit / 2) unit;

  white-space: pre;

  background: var(--ring-secondary-background-color);

  font-family: monospace;
}

.actions {
  display: flex;
  align-items: flex-start;
  flex-direction: column;

  margin-left: unit;
}
