@value enforced-color, inherited-color, own-color from '../Rules.module.css';
@value unit: var(--ring-unit);

.ruleButton {
  display: block;
}

.addNewRule {
  margin-bottom: calc(unit / 2);
  margin-left: calc(unit * 3);
}

.description {
  max-width: calc(unit * 55);
}

.dialog {
  width: calc(unit * 130);
}

.summary {
  margin: 0;

  cursor: pointer;

  color: var(--ring-secondary-color);

  &:hover {
    opacity: 0.8;
  }

  &:not(.onlyInheritedRules) {
    & .own {
      text-decoration-line: underline;

      color: own-color;

      font-weight: var(--ring-font-weight-bold);
    }
  }
}

.table {
  padding-bottom: unit;
}

.inheritedToggle {
  margin-bottom: calc(unit * 4);
}
