@value unit: var(--ring-unit);

.branch {
  padding-top: calc(unit / 2);

  color: var(--ring-secondary-color);

  font-size: var(--ring-font-size-smaller);
  line-height: var(--ring-line-height-lowest);
}

.editButtom {
  padding-bottom: calc(unit / 2);

  opacity: 0;
}

.repositoryWrapper {
  display: flex;
  flex-direction: column;
  gap: calc(unit / 2);
}

.toggle {
  & span:first-child {
    flex-shrink: 0;

    margin-top: 3px;
  }

  & span:nth-child(2) {
    flex: 1;
  }
}

.toggleDeleted {
  cursor: default;

  text-decoration-line: line-through;

  color: var(--ring-secondary-color);
}

.folderRoot {
  padding-top: 2px;
  padding-right: 2px;

  color: var(--ring-secondary-color);
}

.folderContainer {
  display: flex;

  align-items: start;

  & > * {
    transition: opacity var(--ring-ease);
  }

  &:hover .editIcon {
    color: var(--ring-link-hover-color);
  }

  &:hover .editButtom {
    opacity: 1;
  }
}

.formContainer {
  display: flex;

  align-items: baseline;
}

.folder {
  box-sizing: border-box;
  padding-left: 2px;

  color: var(--ring-secondary-color);

  font-size: var(--ring-font-size-smaller);
}

.inputFolder {
  flex: 1;

  padding-left: unit;

  color: var(--ring-secondary-color);

  font-size: var(--ring-font-size-smaller);
}
