@value unit: var(--ring-unit);

.wrapper {
  display: grid;
  grid-template-areas:
    'label terminal'
    'name name';
  grid-template-columns: 1fr;
  row-gap: calc(unit / 4);

  align-items: baseline;

  /* stylelint-disable selector-max-specificity, selector-id-pattern */
  & :global(#SAKURA_AFTER_AGENT_INFO) {
    justify-content: end;

    grid-area: terminal;

    & button {
      color: var(--ring-link-color);

      &:hover {
        color: var(--ring-link-hover-color);
      }
    }
  }
  /* stylelint-enable selector-max-specificity, selector-id-pattern */

  & .agentInfo {
    display: contents;

    white-space: nowrap;

    font-size: var(--ring-font-size-smaller);
    line-height: var(--ring-line-height-lowest);
  }
}

.agentInfoValue {
  min-width: calc(unit * 11);

  text-overflow: ellipsis;
  grid-area: name;

  & > div {
    color: var(--ring-text-color);
  }
}

.agentLink {
  height: calc(100% + calc(unit * 1.5));
  margin: 0 calc(unit * -2);
  padding: 0 calc(unit * 2);
}

.label {
  margin-bottom: 6px;
  grid-area: label;

  color: var(--ring-secondary-color);
}

.labelWrapper {
  display: flex;
  justify-content: space-between;

  min-width: max-content;
}

.compatibleAgents.compatibleAgents {
  display: flex;

  height: calc(100% + calc(unit * 2));
  margin: 0 calc(unit * -2);
  padding: 0 calc(unit * 2);
  grid-area: name;
}

.copyWrapper {
  margin-left: calc(unit / 2);
}

.detachedTooltip {
  margin-left: calc(unit / 2);

  color: var(--ring-icon-color);

  &:hover {
    color: var(--ring-icon-hover-color);
  }
}
