@value unit: var(--ring-unit);

.copyButton {
  float: right;

  transition: opacity var(--ring-ease);

  opacity: 0;
}

.parameter {
  position: relative;

  display: flex;
  align-items: baseline;

  margin-bottom: calc(unit / 2);

  &:hover .parameterActions > * {
    opacity: 1;
  }

  .parameterName,
  .parameterValue {
    display: -webkit-box;
    overflow: hidden;

    flex: 1;

    max-height: calc(unit * 12.5);

    text-overflow: ellipsis;

    line-break: anywhere;
    -webkit-line-clamp: 4;

    line-clamp: 4;

    -moz-box-orient: vertical;
    -webkit-box-orient: vertical;

    font-size: var(--ring-font-size-smaller);

    line-height: var(--ring-line-height-lowest);
  }

  .parameterValue {
    padding-right: calc(unit / 4);
  }
}

.parameterName:hover .copyButton {
  opacity: 1;
}

.inputs.deleted,
.inputs .emptyField {
  .copyButton {
    opacity: 0;
  }
}

.parameterPreview {
  margin-bottom: calc(unit / 2);
  padding-top: calc(unit / 2);
}

.parameterPreviewEdit {
  margin-bottom: calc(unit * 1.5);
  padding-top: calc(unit / 2);
}

.inputContainer {
  max-width: 50%;
  margin: 0 -2px;
}

.inputs {
  display: flex;
  align-items: baseline;
  flex: 1;
  gap: unit;
}

.input {
  text-overflow: ellipsis;
}

.deleted,
.deleted .input {
  text-decoration-line: line-through;

  color: var(--ring-secondary-color);
  -webkit-text-fill-color: var(--ring-secondary-color);
}

.input:disabled {
  background-color: transparent;
}

.parameter:not(:focus-within) .input {
  border-color: transparent;
  background-color: transparent;
}

.parameter:focus-within .input {
  background-color: var(--ring-content-background-color);
}

.parameterActions {
  justify-content: end;

  width: calc(unit * 2);
}

.parameter:focus-within .parameterActions > * {
  visibility: hidden;
}

.emptyField {
  color: var(--ring-secondary-color);
}
