@value unit: var(--ring-unit);

.link {
  display: flex;
  align-items: baseline;
}

.dropdown {
  display: flex;
}

.anchor {
  display: block;

  color: var(--ring-text-color);

  line-height: var(--ring-line-height);
}

.dropdown .anchor {
  line-height: var(--ring-line-height-taller);
}

.popup {
  z-index: 10;

  padding: unit calc(unit * 2);
}

.collapsible {
  cursor: pointer;
}

.expanded {
  margin-bottom: unit;
  margin-left: calc(unit * 3);
}

.chevron {
  margin-right: unit;
}

.entityIcon {
  margin-right: calc(unit / 2);
}
