@value font-smaller-lower from '../../../globals.module.css';
@value unit: var(--ring-unit);

.sidebar {
  display: flex;
  overflow: hidden;
  flex-direction: column;
}

.footer {
  height: calc(5 * unit);

  border-top: 1px solid var(--ring-line-color);

  font-size: var(--ring-font-size-smaller);
}

.projectsTree,
.arrowKeyStepper {
  height: 100%;
}

.projectsTree,
.list {
  outline: none;
}

.content {
  height: 100%;
  margin-top: calc(unit * 1.5);
}

.loader {
  padding-left: calc(unit * 2);

  line-height: calc(unit * 3);

  &:first-child {
    margin-top: 0;
  }
}

.loaderText {
  margin-left: 2px;
}

.placeholder {
  composes: font-smaller-lower;

  display: flex;
  align-items: center;
  flex-direction: column;

  flex-grow: 1;

  color: var(--ring-secondary-color);
}

.createButton {
  margin-top: unit;
}

.nothingFoundBox {
  display: flex;
  align-items: center;
  flex-direction: column;

  width: 100%;
  padding: calc(unit * 10) 0;
}

.nothingFoundBox .message {
  margin: unit calc(unit * 2) calc(unit * 3);

  font-size: var(--ring-font-size);
}

.nothingFoundBox .button {
  display: inline-block;

  padding: 10px 20px;

  cursor: pointer;
  text-align: center;
}

.storyContainer {
  overflow: visible;

  width: 100%;
}
