@value unit: var(--ring-unit);

.linkIcon {
  margin-right: calc(unit / 2);

  color: var(--ring-text-color);

  line-height: normal;
}

.container {
  display: flex;
  overflow: hidden;
  align-items: flex-end;
}

.title {
  flex-grow: 1;

  padding-right: calc(unit * 3 / 2);
}

.favoriteTitle {
  flex-grow: 1;

  padding-left: calc(unit * 2);
}

.favorite {
  display: inline-flex;
  align-items: baseline;
}

.installAgent {
  margin-right: unit;
  margin-left: auto;
}

.buttonInstall {
  margin-left: unit;
}

.selectionItem {
  display: flex;
}

.selection {
  padding-left: calc(unit * 3 / 2);
}

.nonClickableHeader {
  justify-content: space-between;
}

.tail {
  margin-right: unit;
}

.favoriteButton {
  height: calc(unit * 2);
  margin-right: calc(unit / 2);
  margin-left: auto;
}
