@value unit: var(--ring-unit);

.textAreaWrapper {
  position: relative;
}

.textArea {
  min-height: calc(unit * 5.5);

  background-color: var(--ring-content-background-color);

  font-family: var(--ring-font-family-monospace), serif;
}

.parameterActions > * {
  padding: 0;

  transition: opacity var(--ring-ease);

  opacity: 0;
}

.content {
  position: relative;

  display: flex;
  flex-direction: column;
}

.file {
  display: flex;
  align-items: center;
  flex-direction: row;

  padding: calc(unit / 4) 0;

  font-size: var(--ring-font-size-smaller);

  line-height: var(--ring-line-height-lowest);
  column-gap: calc(unit / 2);

  &:hover .parameterActions > * {
    opacity: 1;
  }
}

.labelName {
  padding-bottom: calc(unit / 2);

  color: var(--ring-secondary-color);

  font-size: var(--ring-font-size-smaller);
}

.actions {
  display: flex;
  align-items: end;
  flex-direction: row;
  column-gap: calc(1.5 * unit);

  padding-bottom: calc(unit / 1.5);
}

.fileDeleted {
  text-decoration-line: line-through;

  color: var(--ring-secondary-color);
  -webkit-text-fill-color: var(--ring-secondary-color);
}

.artifactsIcon {
  margin-top: calc(unit / 2);
}
