@value ellipsis from '../../../../globals.module.css';
@value link from '../../../common/BuildNumber/BuildNumber.module.css';
@value unit: var(--ring-unit);

.wrapper {
  display: flex;
  align-items: baseline;
}

.popupContent {
  padding: calc(unit * 2);
  padding-top: calc(unit * 1.5);
}

.anchor {
  color: var(--ring-text-color);
}

.buildPath {
  composes: ellipsis;

  display: flex;
  align-items: baseline;
  flex-wrap: nowrap;

  margin-bottom: calc(unit / 2);

  &:last-child {
    margin-bottom: 0;
  }
}

.buildNumber .link {
  font-size: var(--ring-font-size);
}

.separator {
  color: var(--ring-secondary-color);
}

.chainLink {
  margin-left: calc(unit * 1.5);
}
