@value logoSize: calc(unit * 4);
@value unit: var(--ring-unit);

.buildsTvMode {
  padding: calc(2 * unit) calc(4 * unit);
}

.title {
  padding-bottom: unit;
}

.titleText {
  display: inline-block;

  margin: 0;

  font-weight: var(--ring-font-weight-bold);
}

.titleIcon {
  padding-left: 0;

  vertical-align: top;

  & svg {
    width: logoSize;
    height: logoSize;
  }
}

.hideDropDowns {
  /* stylelint-disable-next-line selector-max-specificity */
  & :global(.icon.toggle) {
    display: none;
  }
}
