@value unit: var(--ring-unit);

.dialog {
  width: calc(unit * 70);
}

.usages {
  padding-top: calc(unit * 3);

  &:empty {
    margin: 0;
    padding: 0;
  }
}

.open {
  padding-bottom: unit;
}

.info {
  display: flex;

  margin-top: unit;

  padding: 10px 12px 12px;

  border: 1px solid #a599ff;

  border-radius: unit;
  background-color: var(--ring-hover-background-color);
}

.infoText {
  margin-left: unit;
}

.infoIcon {
  color: #6f5cff;
}
