@value unit: var(--ring-unit);

.pageWithSidebar {
  display: flex;
  flex: 1;

  margin: 0 calc(var(--tc-page-padding-inline) * -1);
}

.sidebar {
  border-top: 1px solid var(--ring-line-color);
}

.main {
  display: flex;
  overflow-y: auto;
  flex: 1;
  flex-direction: column;
}

.content {
  display: flex;
  align-self: baseline;
  flex: 1 1;
  flex-basis: 0;
  flex-direction: column;

  box-sizing: border-box;
  min-width: 100%;
}

.chart {
  padding: 0 var(--tc-page-padding-inline) calc(unit * 2);
}

.openSidebar {
  & .toolbar,
  & .chart {
    padding-right: calc(unit * 2.5);
  }
}
