@value unit: var(--ring-unit);

.secondary {
  color: var(--ring-secondary-color);
}

.link {
  position: relative;

  overflow: hidden;
}

.othersAvatar {
  transition: opacity var(--ring-fast-ease);

  opacity: 0.5;
}

.linkWrapper {
  position: relative;
  z-index: 0; /* creates an isolated stacking context */
}

.linkWrapper:hover .othersAvatar {
  transition: none;

  opacity: 1;
}

.brancheIcon {
  margin-left: calc(unit / 2);
}
