@value resetButton, font-smaller-lower, ellipsis from '../../../../globals.module.css';
@value chevronWidth: 16px;
@value unit: var(--ring-unit);

.button {
  composes: resetButton;

  width: 100%;
}

.projectsTreeItem {
  position: relative;

  display: block;
  overflow: hidden;

  box-sizing: border-box;

  width: calc(100% - var(--ring-unit) * 3);
  margin: 0 auto;

  padding-left: calc(unit / 2);

  color: var(--ring-text-color);
  border-radius: var(--ring-border-radius);
  outline: none;

  &&:hover {
    padding-left: calc(unit / 2);

    text-decoration: none;

    color: var(--ring-text-color);
    border-radius: var(--ring-border-radius);

    background-color: var(--ring-tag-background-color);
  }

  &&.selected {
    background-color: var(--ring-selected-background-color);
  }
}

.createButton {
  display: none;

  margin-left: 2px;
}

.activeCreateButton,
.projectsTreeItem:hover .createButton {
  display: block;
}

.checkbox {
  display: flex;
  align-items: center;
}

.legacyCheckbox {
  position: relative;
  top: 1px;

  flex-shrink: 0;

  outline: none; /* the whole line is highlighted on focus */
}

.checkboxLabel {
  min-width: 0;
}

.content {
  display: flex;

  align-items: center;

  height: calc(3 * unit);

  padding-right: calc(unit * 3 / 4);

  line-height: calc(2.5 * unit);

  & > * {
    flex-shrink: 0;
  }
}

.offset {
  margin-left: unit;
}

.name {
  composes: ellipsis;

  position: relative;
  z-index: 1;

  flex: 1 1 auto;

  min-width: calc(unit * 5);

  cursor: pointer;
}

.bold {
  font-weight: var(--ring-font-weight-bold);
}

.archived .name {
  color: var(--ring-secondary-color);
}

.active {
  background-color: var(--ring-selected-background-color);
}

.action {
  cursor: pointer;
}

.selected {
  border-radius: var(--ring-border-radius);
  background-color: var(--ring-selected-background-color);
}

.chevronButton {
  position: absolute;
  z-index: 1;
  top: calc(unit / 2);

  padding-right: calc(var(--ring-unit) / 2);
  padding-left: calc(var(--ring-unit) * 2);

  & .chevronIcon {
    transition: none;

    color: var(--ring-icon-secondary-color);
  }

  & .topLevel {
    margin: 0 calc(unit / 4);

    color: var(--ring-text-color);
  }
}

.elementWithChevron {
  height: calc(2 * unit);
  padding-right: calc(unit / 4);
}

.elementWithoutChevron {
  height: calc(2 * unit);
}

.title {
  display: flex;

  box-sizing: border-box;
  width: calc(100% - unit * 3);
  margin: calc(unit) auto;

  letter-spacing: 2px;

  color: var(--ring-text-color);

  font-size: var(--ring-font-size-smaller);
  line-height: calc(3 * unit);
}

.titleWithoutChevron {
  padding: 0 0 0 calc(unit / 2);
}

.titleChevron {
  height: calc(2 * unit);
  padding-left: calc(unit * 2.5);
}

.favoriteChevron {
  height: calc(2 * unit);
  padding-right: calc(unit / 4);
  padding-left: calc(unit * 2);
}

.row:first-child .title {
  margin-top: 0;
}

.gridcell {
  position: relative;
}

.server {
  composes: ellipsis;

  padding: 0 calc(unit + 2px) 0 calc(2 * unit);
}

.serverTitle {
  color: var(--ring-secondary-color);

  font-size: var(--ring-font-size);
}

.serverDetails {
  font-size: var(--ring-font-size-smaller);

  line-height: calc(unit * 3);
}

.dropdown {
  display: block;
}

.tooltip {
  composes: ring-tooltip-tooltip from global;
  composes: ring-tooltip-long from global;

  z-index: var(--ring-alert-z-index);

  &.inPopup {
    z-index: 1000;
  }
}

.highlighting {
  color: var(--tc-highlight-color);
}

.counter {
  white-space: nowrap;
}

.counterIcon {
  margin-right: 2px;
  margin-left: 6px;

  color: var(--ring-icon-color);
}

.warningIcon {
  margin-left: calc(unit / 2);

  color: var(--ring-icon-error-color);
}

.counterText {
  color: var(--ring-secondary-color);

  font-size: var(--ring-font-size-smaller);
  font-weight: normal;
}

.pendingCounter {
  margin-left: 6px;

  color: var(--ring-main-color);

  font-size: var(--ring-font-size-smaller);
  font-weight: normal;
}

.newFailedTestsCounter {
  margin-left: 6px;

  color: var(--ring-error-color);

  font-size: var(--ring-font-size-smaller);
  font-weight: var(--ring-font-weight-bold);
}

.starIcon {
  &.starIcon {
    transition: none;
  }

  &.hovered {
    color: var(--ring-icon-hover-color);
  }
}

.note {
  composes: font-smaller-lower;

  margin-right: 2px;
  margin-left: 6px;

  color: var(--ring-secondary-color);

  font-weight: normal;
}

.linkIcon {
  margin-right: 6px;

  color: var(--ring-text-color);

  line-height: normal;
}

.newWindowLinkIcon {
  margin-left: 6px;

  color: var(--ring-icon-color, #818594);
}

a[data-test='ring-link']:focus-visible {
  box-shadow: inset 0 0 0 2px var(--ring-border-hover-color);
}

div[data-test='ring-title']:focus {
  outline: none;
}

div[data-test='ring-title']:focus-visible {
  border-radius: var(--ring-border-radius);
  box-shadow: inset 0 0 0 2px var(--ring-border-hover-color);
}

.updateButton {
  padding: 0;
}

.iconAction {
  padding: 0 3px;

  &:disabled {
    visibility: hidden;
  }
}

.reordered {
  composes: font-smaller-lower;

  padding: 0 2px 0 calc(unit / 2);

  color: var(--ring-secondary-color);
}

.projectsTreeItem.disabled {
  color: var(--ring-disabled-color);
}

.withOwnPending {
  font-weight: var(--ring-font-weight-bold);
}
