@value unit: var(--ring-unit);

.content {
  position: relative;

  margin: 0 calc(var(--tc-page-padding-inline) * -1) calc(unit * -4);
  padding: 0 var(--tc-page-padding-inline);
}

.content.content h2 {
  font-size: 20px;
  font-weight: normal;
  line-height: 24px;
}

.content h2 > :first-child svg {
  vertical-align: -2px;
}

.firstInfoGroup {
  margin-bottom: calc(unit * 2);
}

.secondInfoGroup {
  margin-bottom: calc(unit * 4);

  & .row {
    margin-bottom: unit;

    &:last-child {
      margin-bottom: 0;
    }
  }
}

.notes:not(:empty) {
  margin-bottom: calc(unit * 1.5);
}

.warning {
  margin-bottom: calc(unit / 2);
}

.snapshotDependenciesChart {
  width: 40%;
}

@media (width <= 1200px) {
  .snapshotDependenciesChart {
    width: 60%;
  }
}

.buildProgress,
.buildLog,
.loader {
  margin-bottom: calc(unit * 4);
}
