@value unit: var(--ring-unit);

.wrapper {
  composes: animation from './Sidebar/Sidebar.module.css';

  position: relative;

  display: flex;

  overflow: hidden;
  flex: 1;
  flex-direction: column;

  box-sizing: border-box;

  background-color: var(--ring-secondary-background-color);
}

.contentWrapper {
  position: relative;

  flex: 1;
}

.content {
  position: absolute;
  top: 0;
  right: 0;
  bottom: 0;
  left: 0;

  display: flex;
  overflow: auto;
  flex-direction: column;
}
