@value font from '../../../globals.module.css';
@value unit: var(--ring-unit);

.container {
  overflow: hidden;

  margin: -2px;

  line-height: var(--ring-line-height-lower);
}

.loading {
  visibility: hidden;
}

.buildPath {
  composes: font;

  position: relative;

  margin: 2px;

  text-overflow: ellipsis;

  font-size: inherit;
  line-height: inherit;
}

.item {
  white-space: nowrap;
}

.link {
  color: inherit;
}

.separator {
  color: var(--ring-secondary-color);
}

.pathItemDropDown {
  display: inline;
}

.hiddenPathAnchor {
  cursor: default;
}

.hiddenPathPopup {
  padding: unit calc(unit * 2);

  color: var(--ring-secondary-color);
}

.ellipsis {
  color: inherit;
}

.withCollapsing {
  overflow: hidden;

  height: var(--ring-line-height-lower);

  white-space: nowrap;
  text-overflow: ellipsis;
}

.invisible {
  position: absolute;
  top: 0;
  left: 0;

  visibility: hidden;
}

.secondary {
  color: var(--ring-secondary-color);
}

.icon {
  margin-right: 2px;
}
