@value unit: var(--ring-unit);

.formInner {
  display: flex;
  flex-direction: column;

  width: 564px;

  padding-top: calc(unit * 2);
  gap: calc(unit * 3);
}

.parentProject {
  display: flex;
  gap: unit;
}

.actions {
  padding-top: calc(unit * 3);
}

.inputs {
  display: flex;
  flex-direction: column;
  gap: calc(unit * 2);
}

.toggleGroup {
  display: flex;
  gap: calc(unit * 2);
}

.toggleRow {
  display: flex;
  align-items: center;
  gap: unit;
}

.toggleAreaIcon {
  margin-bottom: unit;
}

.infoIcon {
  padding-left: 2px;

  color: var(--ring-secondary-color);
}

.buildConfigWarning {
  display: flex;
  align-items: baseline;

  box-sizing: border-box;

  width: 560px;
  height: 72px;
  padding: calc(unit * 1.5) calc(unit * 3);

  cursor: pointer;

  background-color: var(--ring-hover-background-color);
  gap: unit;
}

.warningIcon {
  color: var(--ring-main-color);
}

.link {
  width: 55%;

  font-size: 12px;
}

.cardContent {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
