@value font-smaller-lower from '../../../globals.module.css';
@value unit: var(--ring-unit);

.container {
  width: calc(unit * 50);
  min-height: calc(unit * 20);
  max-height: calc(100vh - unit * 24);
}

.tree {
  height: 100%;
}

.treeContent {
  flex: 1 0 0;

  height: auto;
}

.search {
  width: auto;
}

.searchWrapper {
  padding: unit 12px 0;
}

.placeholder {
  composes: font-smaller-lower;

  margin: calc(unit * 2) 0 0 calc(unit * 4);

  color: var(--ring-secondary-color);
}
