@value unit: var(--ring-unit);

.container {
  padding: 0 calc(unit * 2);
}

.agent.agent {
  margin-left: calc(var(--tc-page-padding-inline) * -1 - 2 * unit);
}

.group {
  display: flex;
  flex-direction: column;

  height: calc(100% - 4 * unit);
  margin-top: 0;
  margin-bottom: calc(2 * unit);
}

.expandable {
  margin: calc(2 * unit) 0 0;
}

.heading {
  color: var(--ring-error-color);
}

.subheading {
  color: var(--ring-secondary-color);
}

.content.content {
  flex: 1 0;

  padding-top: 0;
  padding-bottom: 0;
}
