@value unit: var(--ring-unit);

.container {
  padding: 0 calc(unit * 2);
}

.cloudAgent {
  margin-bottom: calc(0.5 * unit);
}

.agent.agent {
  margin-left: calc(-6 * unit);
}

.expandable {
  margin: 0;
}

.header.header {
  margin: 0 calc(var(--tc-page-padding-inline) * -1);
  padding-right: 0;
}

.heading {
  color: var(--ring-error-color);
}

.subheading {
  color: var(--ring-secondary-color);
}

.content.content {
  flex: 1 0;

  padding-top: 0;
  padding-bottom: 0;
}

.star {
  transition: opacity var(--ring-fast-ease);

  opacity: 0;
}

.expandable:hover .star,
.expandable:focus-within .star {
  transition: none;

  opacity: 1;
}
