@value unit: var(--ring-unit);

.page {
  position: relative;

  display: flex;
  justify-content: center;

  width: 100%;

  & * {
    box-sizing: border-box;
  }
}

.container {
  display: flex;
  flex-direction: row;
  justify-content: center;

  max-width: calc(unit * 150);
  margin-top: 152px;
  margin-left: 120px;
}

.hidden {
  display: none;
}

.content {
  display: flex;
  flex-direction: column;

  padding-bottom: calc(unit * 4);
}

.errorWrapper {
  flex-grow: 1;
}

.loader {
  flex-grow: 1;

  padding-top: calc(unit * 4);
}

.imageWrapper {
  display: flex;
  flex-grow: 1;
  justify-content: center;
}

.image {
  position: sticky;

  margin: 0 124px 300px 148px;
}

.projectForm {
  width: 100%;
  max-width: 800px;
}

.formInner {
  display: grid;
  grid-template-columns: calc(unit * 22.5) auto;
  column-gap: unit;
  row-gap: calc(unit * 3);

  padding-top: calc(unit * 2);
}

.actions {
  padding-top: calc(unit * 3);
}

.parentProjectSelect {
  max-width: calc(unit * 56);
}

.close {
  position: absolute;
  top: 0;
  right: 0;
}
