@value ellipsis from '../../../../globals.module.css';
@value unit: var(--ring-unit);

.open {
  &::before {
    position: absolute;

    z-index: 1;
    top: var(--absolute-child-top);
    right: calc(var(--tc-page-padding-inline) * -1);
    bottom: 0;
    left: calc(var(--tc-page-padding-inline) * -1);

    content: '';
    pointer-events: none;

    box-shadow:
      0 0 0 1px var(--ring-line-color),
      0 2px 8px var(--ring-popup-shadow-color);

    grid-column: start / end;
    grid-row: var(--row) / span 2;
  }
}

.button {
  &::before {
    position: absolute;
    top: 0;
    right: calc(var(--tc-page-padding-inline) * -1);
    bottom: 1px;
    left: calc(var(--tc-page-padding-inline) * -1);

    content: '';
  }

  grid-column: start / end;
  grid-row: var(--row) / span 1;
}

.open.showFiles {
  &::before {
    display: none;
  }
}

.button:focus {
  outline: none;

  &::before {
    box-shadow: inset 2px 0 var(--ring-main-color);
  }
}

.item,
.detailsHeading,
.row {
  display: contents;
}

.detailsWrapper {
  grid-column: start / end;
}

.psevdoItem {
  position: absolute;

  z-index: -1;
  top: var(--absolute-child-top);
  right: 0;
  bottom: 0;
  left: 0;
  grid-column: start / end;
  grid-row: var(--row) / span 2;
}

.closed .psevdoItem[data-faded='true'],
.showFiles .psevdoItem[data-faded='true'] {
  /* stylelint-disable selector-max-specificity */
  & + .detailsHeading .row > *,
  & + .detailsHeading + .detailsWrapper {
    opacity: 0.25;
  }
  /* stylelint-enable */
}

.arrow {
  position: absolute;

  grid-column: -2;
  grid-row: var(--row) / span 1;

  top: calc(var(--absolute-child-top) + 8px);
  right: calc(unit * -4 + 10px);
  left: auto;

  padding: 0;

  transition: opacity ease;

  pointer-events: none;

  opacity: 0;
  color: var(--ring-icon-secondary-color);

  line-height: normal;
}

.chartCol {
  position: relative;

  align-self: start;

  min-width: 0;
  margin-right: calc(unit * -1);
  grid-column-start: chart-start;
  grid-row-start: var(--row);

  padding-top: 6px;
}

.commentCol {
  position: relative;

  min-width: 0;
  grid-column-start: comment-start;
  grid-row-start: var(--row);
}

.commentWrapper {
  display: flex;
  overflow: hidden;

  line-height: var(--ring-line-height);
}

.comment {
  overflow-wrap: break-word;

  overflow: hidden;
}

.singleline {
  composes: ellipsis;

  height: var(--ring-line-height);

  white-space: nowrap !important;
}

.branches {
  margin-left: unit;
}

.authorAndDateCol {
  position: relative;

  display: flex;
  overflow: hidden;
  align-items: baseline;

  grid-column-start: author-date-start;
  grid-row-start: var(--row);
}

.author {
  display: inline-block;

  font-size: var(--ring-font-size-smaller);
}

.datetime {
  margin-left: calc(unit / 2);

  white-space: nowrap;

  color: var(--ring-secondary-color);

  font-size: var(--ring-font-size-smaller);
}

.revisionCol {
  display: flex;
  justify-content: flex-end;

  grid-column-start: revision-start;
  grid-row-start: var(--row);

  color: var(--ring-secondary-color);

  font-size: var(--ring-font-size-smaller);
}

@media (width <= 1200px) {
  .revisionCol {
    display: none;
  }
}

.filesCol {
  display: flex;
  justify-content: flex-end;

  grid-column-start: files-start;
  grid-row-start: var(--row);
}

.actionsCol {
  display: flex;
  align-items: baseline;
  justify-content: flex-end;
  grid-column-start: actions-start;
  grid-row-start: var(--row);
}

.revisionCol,
.filesCol {
  text-align: right;

  font-size: var(--ring-font-size-smaller);
}

.commentCol,
.authorAndDateCol,
.revisionCol,
.filesCol,
.actionsCol {
  position: relative;

  padding-top: 6px;
  padding-bottom: 6px;

  &:first-child {
    margin-left: 0;
  }
}

.changeFromSnapshotDependencyIcon,
.settingsIcon,
.personalIcon {
  height: unset;
  margin-right: calc(unit / 2);

  line-height: var(--ring-line-height);
}

.myPersonalIcon {
  color: var(--ring-main-color);
}

.multylineIcon {
  margin-left: calc(unit / 2);

  color: var(--ring-icon-secondary-color);
}

.externalViewer {
  margin-right: calc(unit * 2);

  line-height: 12px;
}

.actionsAnchor {
  height: unset;
  padding: 0;

  line-height: var(--ring-line-height);
}

.outerContainer {
  position: relative;

  overflow: hidden;

  height: calc(unit * 11);
  margin: 0 calc(var(--tc-page-padding-inline) * -1);
}

.innerContainer {
  position: absolute;
  top: 0;
  right: 0;
  left: 0;

  padding: 0 var(--tc-page-padding-inline);
}

.showFiles {
  & .innerContainer {
    border-bottom: 1px solid var(--ring-line-color);
  }
}

.smallPadding {
  &.open::before {
    right: calc(unit * -2);
    left: calc(unit * -2);
  }

  & .arrow {
    top: 5px;
    right: calc(unit * -4.5);
  }

  & .commentCol,
  & .authorAndDateCol,
  & .revisionCol,
  & .filesCol,
  & .actionsCol {
    padding: 0;

    padding-top: 2px;
    padding-bottom: 2px;
  }

  & .button::before {
    right: calc(unit * -2);
    left: calc(unit * -2);
  }

  & .outerContainer {
    margin: 0 calc(unit * -2);
  }

  & .innerContainer {
    padding: 0 calc(unit * 2);
  }
}

.item:hover .arrow,
.button:focus ~ .arrow {
  transition: none;

  opacity: 1;
}

.button:active ~ .arrow {
  transition: none;

  opacity: 1;
  color: var(--ring-main-color);
}

.jobDetailsSidebarTarget {
  &.open::before {
    left: calc(unit * -2.5);
  }

  & .button::before {
    left: calc(unit * -2.5);
  }
}

/* stylelint-disable selector-max-specificity */
.closed:hover .button,
.closed .button:focus,
.closed .psevdoItem[data-hovered='true'] + .detailsHeading .button {
  &::before {
    background-color: var(--ring-selected-background-color);
  }
}
/* stylelint-enable */
