@import '../../common/Avatar/Avatar.module.css';

@value unit: var(--ring-unit);

.container {
  --tc-navigation-background-color: var(--ring-navigation-background-color);

  position: fixed;
  z-index: calc(var(--ring-fixed-z-index) + 1); /* has to be above the subnavigation */
  top: 0;
  bottom: 0;
  left: 0;

  overflow-x: hidden;

  overflow-y: auto;

  min-width: calc(var(--ring-unit) * 8);

  background-color: var(--tc-navigation-background-color);
}

.nightly {
  --tc-navigation-background-color: #00031e;

  background-image: url('Stars.svg');
}

.nightly::before {
  position: absolute;
  top: calc(60% - 18 * unit);
  right: -10px;

  width: calc(36 * unit);

  height: calc(36 * unit);

  content: '';
  filter: blur(40px);

  border-radius: 50%;
  background-image: linear-gradient(
    180deg,
    rgba(28, 30, 111, 0.6) 0%,
    rgba(70, 70, 94, 0.6) 50%,
    rgba(0, 2, 123, 0.6) 100%
  );
}

/* inner theme provider */
.container > div {
  height: 100%;
}

html:global(.ring-variables_dark-dark) .container,
html:global(.ring-ui-theme-dark) .container {
  box-shadow: inset -1px 0 var(--ring-line-color);
}

.header {
  position: relative; /* to position above .nightly::before */

  width: calc(unit * 8);

  background-color: transparent;
}

.text {
  color: var(--ring-text-color);
}

.tray {
  flex: 1;
  justify-content: flex-end;

  margin: 0;
  justify-items: flex-end;
}

.tray.tray {
  padding-top: unit;
}

.popup :global(.ring-list-hint) {
  font-size: var(--ring-font-size-smaller);
  line-height: var(--ring-line-height-lowest);
  padding-block: unit;
}

.tryPipelinesLink {
  display: inline-flex;
}

.tryPipelinesNewTagWrapper {
  margin-left: unit;

  & > :global(.ring-tag-container) {
    display: inline-flex;
    align-items: baseline;
  }
}
