@value unit: var(--ring-unit);

.controls {
  display: flex;
  flex-wrap: wrap;

  margin-top: calc(unit * 1.5);
}

.buttonGroup,
.uploadButton {
  margin-left: unit;
}

.table {
  margin-top: calc(unit * 1.5);
}

/* stylelint-disable selector-class-pattern */
.table :global(.ring-table-cell:first-child),
.table :global(.ring-table-headerCell:first-child) {
  padding-left: 0;
}
/* stylelint-enable selector-class-pattern */

.recipeNameColumn {
  display: flex;
  flex-direction: column;

  min-width: calc(var(--ring-unit) * 37);
  max-width: calc(var(--ring-unit) * 120);
  padding-top: 1px;
  padding-bottom: unit;
}

.recipeTitle {
  line-height: var(--ring-line-height-taller);
}

.recipeId {
  color: var(--ring-secondary-color);

  line-height: 1;
}

.disabled {
  & .recipeTitle,
  & .recipeId {
    color: var(--ring-disabled-color);
  }
}

.item {
  cursor: pointer;
  vertical-align: baseline;

  border-bottom: 1px solid var(--ring-line-color);

  &:hover {
    background: var(--ring-hover-background-color);
  }
}

.column {
  color: blue;
}

.anchor {
  color: var(--ring-text-color);
}

.popup {
  padding: unit calc(unit * 2);
}

.link {
  display: block;
}

.moreLink {
  min-width: calc(unit * 20);
}

.helpIcon {
  margin-left: calc(unit / 2);
}

.empty {
  padding-top: unit;

  color: var(--ring-secondary-color);

  font-style: var(--ring-font-size-larger);
}

.spring {
  display: block;

  margin-bottom: 8px;
}

.titleColumn {
  width: 100%;
}

.moreColumn {
  min-width: calc(unit * 3);
}
