@value unit: var(--ring-unit);

.container {
  margin: 0 calc(var(--tc-page-padding-inline) * -1) 0 calc(unit * -2);
  padding: unit var(--tc-page-padding-inline) 0 calc(unit * 2);
}

.inheritedSection {
  margin: 0 calc(var(--tc-page-padding-inline) * -1);
  padding: calc(unit / 2) var(--tc-page-padding-inline);
}

.wrapper {
  padding-left: calc(unit * 3);
}

.editable:hover {
  cursor: pointer;

  background: var(--ring-hover-background-color);
}

.policiesContainer {
  display: flex;

  width: 100%;
}

.rules {
  flex-direction: column;
}

.policies {
  padding: calc(unit * 2) 0;
}

.actions {
  composes: actions from './Rules/RulesList/RuleItem/RuleItem.module.css';
}

.actionButton {
  composes: actionButton from './Rules/RulesList/RuleItem/RuleItem.module.css';
}

.policyListing {
  flex-grow: 1;

  width: calc(unit * 67);
}

.icon {
  margin-right: calc(unit / 2);
}

.policy {
  display: flex;
}

.inherited {
  color: var(--ring-secondary-color);
}

.disabled,
.disabled .inherited {
  color: var(--ring-disabled-color);
}

.caption {
  margin: 0;
  padding: 0;
}

.helpIcon {
  composes: helpIcon from '../CleanupProjectPage.module.css';
}

.helpPopup {
  max-width: calc(unit * 40);
  padding: unit calc(unit * 2) calc(unit * 2);
}
